insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f4000000-0000-0000-0000-000000000001', 'mrcp1', 'c54ada26-f1f1-48ab-a7a3-86325e8f2b78',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f4000000-0000-0000-0000-000000000001', 'A', 'Adjustment disorder', false, 'Ruled out because adjustment disorder occurs in response to a specific identifiable stressor and is generally less severe/prolonged, whereas this presentation meets full criteria for a major depressive episode with core and associated symptoms present for a sustained period.', 1),
('f4000000-0000-0000-0000-000000000001', 'B', 'Major depressive disorder', true, 'Correct. Persistent low mood and anhedonia (core symptoms), present for at least two weeks (here three months), most of the day nearly every day, alongside biological symptoms (sleep, appetite change) and cognitive symptoms (worthlessness, suicidal ideation), meets diagnostic criteria for a major depressive episode.', 2),
('f4000000-0000-0000-0000-000000000001', 'C', 'Bipolar disorder, current depressive episode', false, 'Ruled out because there is no history given of previous manic or hypomanic episodes; without evidence of past elevated mood episodes, unipolar major depressive disorder is the more likely diagnosis.', 3),
('f4000000-0000-0000-0000-000000000001', 'D', 'Normal bereavement', false, 'Ruled out because there is no mention of a recent bereavement, and the severity and duration of symptoms described (including suicidal ideation) exceed what would be expected in straightforward grief.', 4),
('f4000000-0000-0000-0000-000000000001', 'E', 'Dysthymia (persistent depressive disorder)', false, 'Ruled out because dysthymia describes a more chronic, lower-grade depressive state lasting at least two years, not this shorter, more acute and severe presentation meeting full major depressive episode criteria.', 5),
('f4000000-0000-0000-0000-000000000002', 'A', 'Mania (bipolar disorder, current manic episode)', true, 'Correct. A distinct period of abnormally elevated or irritable mood with increased energy, reduced need for sleep, pressured speech, grandiosity, impulsive/risky behaviour (excessive spending), and impaired insight, lasting at least a week and causing significant impairment, defines a manic episode, indicating bipolar disorder.', 1),
('f4000000-0000-0000-0000-000000000002', 'B', 'Hypomania', false, 'Ruled out because hypomania is a milder, shorter episode (typically at least 4 days) without the marked functional impairment, psychotic features, or need for hospitalisation seen here; this presentation, with significant impairment and lack of insight, meets criteria for full mania.', 2),
('f4000000-0000-0000-0000-000000000002', 'C', 'Generalised anxiety disorder', false, 'Ruled out because GAD causes persistent excessive worry, not the elevated mood, grandiosity and reduced need for sleep described here, which are specific to mania.', 3),
('f4000000-0000-0000-0000-000000000002', 'D', 'Acute stress reaction', false, 'Ruled out because there is no described acute stressor, and the specific constellation of elevated mood, grandiosity and reduced sleep need is characteristic of mania, not a stress reaction.', 4),
('f4000000-0000-0000-0000-000000000002', 'E', 'Attention deficit hyperactivity disorder', false, 'Ruled out because ADHD is a lifelong neurodevelopmental pattern, not an acute, discrete episode of elevated mood and grandiosity as described here, which is characteristic of mania.', 5),
('f4000000-0000-0000-0000-000000000003', 'A', 'Lithium is directly hepatotoxic, requiring renal monitoring to detect this', false, $x$Ruled out because lithium's main long-term organ toxicity concerns are renal (and thyroid) function, not hepatotoxicity; renal monitoring specifically addresses the nephrotoxic risk.$x$, 1),
('f4000000-0000-0000-0000-000000000003', 'B', 'Renal monitoring is done to detect lithium-induced bone marrow suppression', false, 'Ruled out because bone marrow suppression is not a recognised significant adverse effect of lithium; renal monitoring specifically addresses nephrotoxicity, not haematological toxicity.', 2),
('f4000000-0000-0000-0000-000000000003', 'C', 'Lithium has no significant renal effects; monitoring is purely precautionary with no specific rationale', false, 'Ruled out because lithium has a well-established, clinically significant association with nephrogenic diabetes insipidus and chronic kidney disease, making this monitoring specifically evidence-based rather than purely precautionary.', 3),
('f4000000-0000-0000-0000-000000000003', 'D', 'Long-term lithium use can cause nephrogenic diabetes insipidus and chronic kidney disease', true, 'Correct. Long-term lithium therapy is associated with nephrogenic diabetes insipidus (impaired renal concentrating ability) and, over time, chronic kidney disease; regular monitoring of renal function (alongside thyroid function and lithium levels) is essential for patients on long-term treatment.', 4),
('f4000000-0000-0000-0000-000000000003', 'E', 'Renal monitoring is only relevant if the patient develops symptoms of toxicity', false, $x$Ruled out because routine, regular monitoring (typically every 6 months once stable) is recommended proactively, rather than waiting for symptoms to develop, given lithium's narrow therapeutic index and cumulative renal risk.$x$, 5),
('f4000000-0000-0000-0000-000000000004', 'A', 'A simple allergic reaction to the ACE inhibitor', false, 'Ruled out because an allergic reaction would not typically cause this specific neurological symptom complex (tremor, ataxia, confusion); this pattern is characteristic of lithium toxicity from the recognised drug interaction.', 1),
('f4000000-0000-0000-0000-000000000004', 'B', 'Worsening of her underlying bipolar disorder', false, 'Ruled out because the clear temporal relationship to starting an interacting medication, combined with the specific symptom pattern (tremor, ataxia, confusion, vomiting), points to lithium toxicity rather than a mood episode.', 2),
('f4000000-0000-0000-0000-000000000004', 'C', 'Lithium toxicity precipitated by reduced renal lithium clearance from the ACE inhibitor', true, 'Correct. ACE inhibitors reduce renal blood flow and glomerular filtration in a way that can significantly reduce lithium clearance, raising lithium levels into the toxic range; tremor, confusion, ataxia and vomiting are classic features of lithium toxicity, requiring urgent lithium level measurement and management.', 3),
('f4000000-0000-0000-0000-000000000004', 'D', 'Hypertensive encephalopathy from poorly controlled blood pressure', false, 'Ruled out because there is no mention of severely elevated blood pressure, and the specific symptom pattern and clear drug interaction context point to lithium toxicity.', 4),
('f4000000-0000-0000-0000-000000000004', 'E', 'Serotonin syndrome', false, 'Ruled out because there is no mention of a serotonergic drug being introduced, and the specific interaction and symptom pattern described are characteristic of lithium toxicity from reduced renal clearance.', 5),
('f4000000-0000-0000-0000-000000000005', 'A', 'A further trial of a different oral antidepressant only', false, 'Ruled out because he has already failed multiple adequate trials of antidepressant medication; given the severity and risk described, ECT offers a more effective and rapid option than continuing to cycle through oral medications alone.', 1),
('f4000000-0000-0000-0000-000000000005', 'B', 'Watchful waiting with no active treatment change', false, 'Ruled out because significant risk of self-harm in the context of severe, treatment-resistant depression requires active escalation of treatment, not watchful waiting.', 2),
('f4000000-0000-0000-0000-000000000005', 'C', 'Long-term benzodiazepine monotherapy', false, 'Ruled out because benzodiazepines are not an effective treatment for the underlying depressive illness and are not appropriate monotherapy for severe, treatment-resistant depression.', 3),
('f4000000-0000-0000-0000-000000000005', 'D', 'Discharge with no follow-up', false, 'Ruled out because this represents a high-risk clinical scenario requiring active, escalated treatment and close follow-up, not discharge without further management.', 4),
('f4000000-0000-0000-0000-000000000005', 'E', 'Electroconvulsive therapy', true, 'Correct. Electroconvulsive therapy is an effective treatment for severe, treatment-resistant depression, particularly when there is significant risk (e.g. from severe suicidality, psychotic features, or life-threatening reduced oral intake), and can produce a more rapid response than further medication trials in this context.', 5),
('f4000000-0000-0000-0000-000000000006', 'A', 'Neuroleptic malignant syndrome', false, 'Ruled out because NMS is associated with antipsychotic (dopamine-blocking) drugs, causes rigidity and hyporeflexia (not hyperreflexia), and typically has a slower onset over days, unlike the rapid-onset hyperreflexia described here.', 1),
('f4000000-0000-0000-0000-000000000006', 'B', 'Opioid withdrawal', false, 'Ruled out because this patient has just started tramadol (an opioid), not stopped one, making withdrawal an inappropriate explanation for these acute-onset symptoms.', 2),
('f4000000-0000-0000-0000-000000000006', 'C', 'Simple anxiety exacerbation', false, 'Ruled out because the specific combination of hyperreflexia, tremor and diarrhoea, with a clear temporal relationship to combining two serotonergic drugs, points to a specific toxidrome (serotonin syndrome), not simple anxiety.', 3),
('f4000000-0000-0000-0000-000000000006', 'D', 'Anaphylaxis to tramadol', false, 'Ruled out because anaphylaxis would present with urticaria, angioedema and/or bronchospasm, not the specific neuromuscular and autonomic features (hyperreflexia, tremor) described here.', 4),
('f4000000-0000-0000-0000-000000000006', 'E', 'Serotonin syndrome', true, 'Correct. Agitation, sweating, tremor, hyperreflexia and diarrhoea developing shortly after combining two serotonergic drugs (an SSRI and tramadol, which also has serotonergic activity) is characteristic of serotonin syndrome, caused by excess serotonergic activity; management involves stopping the causative drugs and supportive care.', 5),
('f4000000-0000-0000-0000-000000000007', 'A', $x$'Baby blues'$x$, false, 'Ruled out because baby blues is typically mild, self-limiting, and resolves within the first two weeks postpartum, whereas this presentation at four weeks with persistent, significant symptoms indicates a more sustained depressive illness.', 1),
('f4000000-0000-0000-0000-000000000007', 'B', 'Postnatal depression', true, $x$Correct. Persistent low mood, tearfulness, and feelings of inadequacy as a parent, presenting beyond the first two weeks postpartum (distinguishing it from the milder, self-limiting 'baby blues'), with distressing but ego-dystonic intrusive thoughts (common in postnatal depression and anxiety, and importantly different from psychotic ideas), is characteristic of postnatal depression.$x$, 2),
('f4000000-0000-0000-0000-000000000007', 'C', 'Postpartum psychosis', false, 'Ruled out because postpartum psychosis involves psychotic symptoms (delusions, hallucinations, thought disorder) with a much more acute, severe onset, not the mood and anxiety symptoms with distressing but recognised-as-abnormal (ego-dystonic) intrusive thoughts described here.', 3),
('f4000000-0000-0000-0000-000000000007', 'D', 'Normal adjustment to parenthood requiring no intervention', false, 'Ruled out because the persistence, severity and distressing intrusive thoughts described exceed what would be considered a normal adjustment, and warrant assessment and support/treatment.', 4),
('f4000000-0000-0000-0000-000000000007', 'E', 'Generalised anxiety disorder unrelated to childbirth', false, 'Ruled out because the clear postpartum timing and the combination of depressive and anxious symptoms specific to the parenting context point to postnatal depression, rather than a coincidental, unrelated anxiety disorder.', 5),
('f4000000-0000-0000-0000-000000000008', 'A', 'Major depressive disorder, single episode', false, 'Ruled out because a single episode implies a discrete period meeting full criteria for major depression, not this chronic, decade-long pattern of low-grade symptoms that never reached full episode criteria.', 1),
('f4000000-0000-0000-0000-000000000008', 'B', 'Cyclothymia', false, 'Ruled out because cyclothymia involves alternating periods of hypomanic and depressive symptoms not meeting full criteria for either, whereas this presentation describes purely persistent low mood without any elevated mood periods.', 2),
('f4000000-0000-0000-0000-000000000008', 'C', 'Normal personality variation requiring no diagnosis', false, 'Ruled out because the chronicity and persistence of low-grade depressive symptoms over a decade represents a recognised clinical entity (persistent depressive disorder) rather than simply normal personality variation.', 3),
('f4000000-0000-0000-0000-000000000008', 'D', 'Persistent depressive disorder (dysthymia)', true, $x$Correct. A chronic, low-grade depressive state lasting at least two years, without meeting full criteria for a major depressive episode at any point, is characteristic of persistent depressive disorder (dysthymia), though patients can also experience superimposed major depressive episodes ('double depression').$x$, 4),
('f4000000-0000-0000-0000-000000000008', 'E', 'Bipolar II disorder', false, 'Ruled out because there is no history of hypomanic episodes described, which would be required for a diagnosis of bipolar II disorder; this presentation describes purely depressive symptoms.', 5),
('f4000000-0000-0000-0000-000000000009', 'A', 'No changes are needed as valproate teratogenicity only concerns pregnant women taking the drug themselves', false, 'Ruled out because current guidance specifically extends caution to male patients planning to father a child, given emerging evidence of potential risks, alongside the well-established risks when the mother herself takes valproate during pregnancy.', 1),
('f4000000-0000-0000-0000-000000000009', 'B', 'He should simply double his current dose to improve control before conception', false, 'Ruled out because this does not address the relevant safety consideration regarding conception planning, and dose changes should not be made without appropriate clinical indication and specialist review.', 2),
('f4000000-0000-0000-0000-000000000009', 'C', $x$Sodium valproate carries significant teratogenic risk and should be reviewed with specialist input, particularly important given his partner's reproductive plans$x$, true, 'Correct. Sodium valproate is teratogenic and is now subject to strict prescribing restrictions in individuals who could father a child with a partner who might become pregnant, given evidence of potential effects via the paternal line as well as the well-established major risk when taken by a pregnant woman; this warrants specialist review and full counselling before conception is attempted.', 3),
('f4000000-0000-0000-0000-000000000009', 'D', 'Valproate should be stopped abruptly with no alternative arranged', false, 'Ruled out because abrupt cessation of an effective mood stabiliser risks relapse of his bipolar disorder; any medication changes should be carefully planned with specialist input, considering both his mental health stability and reproductive safety.', 4),
('f4000000-0000-0000-0000-000000000009', 'E', 'This consideration is irrelevant, as valproate has no relevant safety profile regarding conception', false, 'Ruled out because valproate has well-recognised, clinically important safety considerations relevant to conception planning, making this a genuinely relevant and important discussion point, not an irrelevant one.', 5),
('f4000000-0000-0000-0000-000000000010', 'A', 'Combination of an antidepressant and an antipsychotic medication', true, 'Correct. Depression with psychotic features (psychotic depression) is treated with a combination of an antidepressant and an antipsychotic medication, as antidepressant monotherapy alone is generally less effective for the psychotic symptoms in this specific presentation; ECT is also an effective option, particularly in severe or urgent cases.', 1),
('f4000000-0000-0000-0000-000000000010', 'B', 'Antidepressant monotherapy alone', false, 'Ruled out because psychotic depression typically responds less well to antidepressant monotherapy alone; combination treatment with an antipsychotic is the standard evidence-based approach.', 2),
('f4000000-0000-0000-0000-000000000010', 'C', 'Antipsychotic monotherapy alone, without an antidepressant', false, 'Ruled out because the underlying mood disorder (depression) also requires specific treatment; antipsychotic monotherapy alone would not adequately address the depressive component of this combined presentation.', 3),
('f4000000-0000-0000-0000-000000000010', 'D', 'Benzodiazepine monotherapy', false, 'Ruled out because benzodiazepines do not treat the underlying depressive or psychotic symptoms and are not appropriate as sole treatment for psychotic depression.', 4),
('f4000000-0000-0000-0000-000000000010', 'E', 'Psychological therapy alone, without medication', false, 'Ruled out because severe depression with psychotic features requires pharmacological (and potentially ECT) treatment; psychological therapy alone is not considered adequate as the sole treatment for this severity and presentation.', 5),
('f4000000-0000-0000-0000-000000000011', 'A', 'Brief psychotic disorder', false, 'Ruled out because brief psychotic disorder involves symptoms lasting less than one month with eventual full return to premorbid functioning, not this 6-month, functionally impairing presentation.', 1),
('f4000000-0000-0000-0000-000000000011', 'B', 'Schizoaffective disorder', false, 'Ruled out because schizoaffective disorder requires a concurrent major mood episode alongside the psychotic symptoms; there is no mood episode described here, making schizophrenia the more likely diagnosis.', 2),
('f4000000-0000-0000-0000-000000000011', 'C', 'Substance-induced psychosis', false, 'Ruled out because the stem specifically states symptoms are not attributable to substance use, excluding this as the diagnosis.', 3),
('f4000000-0000-0000-0000-000000000011', 'D', 'Delusional disorder', false, 'Ruled out because delusional disorder involves an isolated, non-bizarre delusion without other psychotic symptoms (hallucinations, disorganisation) or significant functional decline, unlike this presentation with both hallucinations and delusions plus functional impairment.', 4),
('f4000000-0000-0000-0000-000000000011', 'E', 'Schizophrenia', true, 'Correct. Persistent psychotic symptoms (auditory hallucinations with running commentary, a fixed persecutory delusion) lasting more than 6 months, with functional decline, in the absence of substance use or a mood episode explaining the symptoms, meets criteria for schizophrenia.', 5),
('f4000000-0000-0000-0000-000000000012', 'A', 'Neuroleptic malignant syndrome', true, $x$Correct. Fever, marked muscle rigidity ('lead-pipe' rigidity), confusion, autonomic instability and a markedly raised creatine kinase, occurring after starting an antipsychotic medication, is characteristic of neuroleptic malignant syndrome, a rare but life-threatening complication requiring immediate drug cessation and supportive care.$x$, 1),
('f4000000-0000-0000-0000-000000000012', 'B', 'Serotonin syndrome', false, 'Ruled out because serotonin syndrome is associated with serotonergic drugs (not antipsychotics), causes hyperreflexia and clonus (rather than the rigidity of NMS), and typically has a more rapid onset.', 2),
('f4000000-0000-0000-0000-000000000012', 'C', 'Simple extrapyramidal side effects (acute dystonia)', false, 'Ruled out because acute dystonia causes localised, sustained muscle spasms (e.g. torticollis, oculogyric crisis) without the fever, marked CK elevation and autonomic instability seen in NMS, which is a more severe, systemic syndrome.', 3),
('f4000000-0000-0000-0000-000000000012', 'D', 'Malignant hyperthermia', false, 'Ruled out because malignant hyperthermia is triggered by specific anaesthetic agents (e.g. volatile anaesthetics, suxamethonium) in genetically susceptible individuals, not antipsychotic medication, though the clinical picture can appear similar.', 4),
('f4000000-0000-0000-0000-000000000012', 'E', 'Simple infection unrelated to medication', false, 'Ruled out because the specific combination of rigidity, confusion, autonomic instability and markedly raised CK, temporally linked to starting an antipsychotic, is characteristic of NMS rather than a coincidental infection.', 5),
('f4000000-0000-0000-0000-000000000013', 'A', 'Neuroleptic malignant syndrome, requiring immediate cessation of all medication and ICU admission', false, 'Ruled out because NMS presents with fever, generalised rigidity, confusion and autonomic instability over a more prolonged course, not this acute, localised dystonic spasm; the treatment approach (anticholinergic) also differs.', 1),
('f4000000-0000-0000-0000-000000000013', 'B', 'Tardive dyskinesia, requiring dose reduction over weeks', false, 'Ruled out because tardive dyskinesia develops after months to years of antipsychotic exposure and causes choreiform, repetitive movements, not this acute, sudden-onset dystonic spasm occurring hours after starting treatment.', 2),
('f4000000-0000-0000-0000-000000000013', 'C', 'A simple seizure, requiring anticonvulsant treatment', false, 'Ruled out because this presentation (sustained dystonic posturing without loss of consciousness) is not consistent with a seizure, and the clear temporal relationship to starting an antipsychotic points to an acute dystonic reaction.', 3),
('f4000000-0000-0000-0000-000000000013', 'D', 'Acute dystonic reaction, treated with an anticholinergic agent (e.g. procyclidine)', true, 'Correct. Sudden, sustained muscle spasm affecting the neck (torticollis) and eyes (oculogyric crisis) shortly after starting an antipsychotic is an acute dystonic reaction, an extrapyramidal side effect from dopamine blockade; it responds rapidly to an anticholinergic agent such as procyclidine or benztropine.', 4),
('f4000000-0000-0000-0000-000000000013', 'E', 'Akathisia, requiring a beta-blocker', false, 'Ruled out because akathisia causes subjective inner restlessness with an inability to sit still, not this sustained, localised dystonic muscle spasm; the treatment for akathisia also differs (beta-blockers or benzodiazepines) from that for dystonia.', 5),
('f4000000-0000-0000-0000-000000000014', 'A', 'Acute dystonic reaction', false, 'Ruled out because acute dystonia occurs within hours to days of starting treatment and causes sustained muscle spasm, not this delayed-onset, repetitive choreiform movement pattern developing after years of treatment.', 1),
('f4000000-0000-0000-0000-000000000014', 'B', 'Tardive dyskinesia', true, 'Correct. Repetitive, involuntary orofacial movements (lip-smacking, tongue protrusion, grimacing) developing after long-term (months to years) antipsychotic use is characteristic of tardive dyskinesia, thought to result from dopamine receptor supersensitivity following prolonged dopamine blockade; it can be persistent and difficult to treat, making prevention (using the lowest effective antipsychotic dose) important.', 2),
('f4000000-0000-0000-0000-000000000014', 'C', 'Parkinsonism secondary to antipsychotic use', false, 'Ruled out because drug-induced parkinsonism causes bradykinesia, rigidity and tremor, not the repetitive orofacial movements described here, which are specific to tardive dyskinesia.', 3),
('f4000000-0000-0000-0000-000000000014', 'D', 'Akathisia', false, 'Ruled out because akathisia causes subjective restlessness with an urge to move, not these specific involuntary orofacial movements.', 4),
('f4000000-0000-0000-0000-000000000014', 'E', 'Normal age-related movements requiring no specific attribution', false, 'Ruled out because this specific movement pattern, in the context of long-term antipsychotic use, is a recognised drug-induced complication (tardive dyskinesia), not simply a normal ageing phenomenon.', 5),
('f4000000-0000-0000-0000-000000000015', 'A', 'Regular renal function monitoring as the primary concern', false, 'Ruled out because although general health monitoring is important, the specific, mandatory monitoring requirement unique to clozapine relates to agranulocytosis risk via full blood count, not renal function.', 1),
('f4000000-0000-0000-0000-000000000015', 'B', 'Regular liver function monitoring as the primary concern', false, 'Ruled out because although liver function can be monitored as part of general care, the specific, mandatory, life-saving monitoring requirement for clozapine is full blood count surveillance for agranulocytosis.', 2),
('f4000000-0000-0000-0000-000000000015', 'C', 'Regular full blood count monitoring to detect agranulocytosis', true, 'Correct. Clozapine carries a risk of potentially fatal agranulocytosis, requiring mandatory, regular full blood count monitoring (typically weekly initially, then less frequently once stable) throughout treatment via a registered monitoring service, with treatment stopped immediately if significant neutropenia develops.', 3),
('f4000000-0000-0000-0000-000000000015', 'D', 'No specific monitoring is required beyond standard antipsychotic follow-up', false, 'Ruled out because clozapine has a unique, mandatory monitoring requirement (regular FBC) not required for other antipsychotics, reflecting its specific agranulocytosis risk.', 4),
('f4000000-0000-0000-0000-000000000015', 'E', 'Regular thyroid function monitoring as the primary concern', false, 'Ruled out because thyroid function monitoring is not the specific, defining mandatory requirement for clozapine; the agranulocytosis risk and associated FBC monitoring is the key safety consideration.', 5),
('f4000000-0000-0000-0000-000000000016', 'A', $x$Schizoaffective disorder simply means having both schizophrenia and depression diagnosed at different points in a patient's life$x$, false, 'Ruled out because this does not reflect the specific diagnostic requirement of psychotic symptoms occurring independently of, as well as during, mood episodes within the same overall illness course.', 1),
('f4000000-0000-0000-0000-000000000016', 'B', 'There is no meaningful clinical distinction between these presentations', false, 'Ruled out because these represent genuinely distinct diagnostic categories with specific criteria, relevant to prognosis and treatment planning, not an arbitrary or meaningless distinction.', 2),
('f4000000-0000-0000-0000-000000000016', 'C', $x$Schizoaffective disorder is diagnosed purely based on family history, regardless of the patient's own symptom pattern$x$, false, $x$Ruled out because the diagnosis is based on the patient's own longitudinal symptom pattern (the specific relationship between psychotic and mood symptoms), not family history.$x$, 3),
('f4000000-0000-0000-0000-000000000016', 'D', 'In schizoaffective disorder, psychotic symptoms occur both during and independently of the mood episode, for a substantial portion of the illness', true, 'Correct. Schizoaffective disorder is diagnosed when there is a period of psychotic symptoms occurring in the absence of a mood episode, in addition to psychotic symptoms occurring concurrently with mood episodes, distinguishing it from schizophrenia with a comorbid mood episode (where the diagnosis would depend on the specific temporal relationship and predominance of symptoms) or from a mood disorder with mood-congruent psychotic features (where psychosis only occurs during mood episodes).', 4),
('f4000000-0000-0000-0000-000000000016', 'E', 'Schizoaffective disorder requires psychotic symptoms to always be absent during mood episodes', false, 'Ruled out because this is the opposite of the actual diagnostic principle; psychotic symptoms do occur during mood episodes in schizoaffective disorder, but critically also occur independently of them, which is the key distinguishing feature.', 5),
('f4000000-0000-0000-0000-000000000017', 'A', 'Schizophrenia', false, 'Ruled out because schizophrenia requires symptoms (with significant functional impact) persisting for at least 6 months, not this brief, fully resolving episode lasting under a month.', 1),
('f4000000-0000-0000-0000-000000000017', 'B', 'Schizophreniform disorder', false, 'Ruled out because schizophreniform disorder describes symptoms lasting between one and six months, exceeding the duration described here (three weeks, resolving).', 2),
('f4000000-0000-0000-0000-000000000017', 'C', 'Normal grief reaction without psychosis', false, 'Ruled out because true psychotic symptoms (delusions and hallucinations, not simply preoccupation with the deceased) are described, which exceeds what is considered a normal grief reaction, even though the stressor (bereavement) is a recognised trigger for brief psychotic disorder.', 3),
('f4000000-0000-0000-0000-000000000017', 'D', 'Delusional disorder', false, 'Ruled out because delusional disorder involves a persistent (at least one month, often much longer) isolated delusion without other psychotic features, not this brief, fully resolving episode with both delusions and hallucinations.', 4),
('f4000000-0000-0000-0000-000000000017', 'E', 'Brief psychotic disorder', true, 'Correct. A sudden onset of psychotic symptoms, often following a significant stressor, lasting less than one month with eventual full return to premorbid functioning, defines brief psychotic disorder, distinguishing it from schizophrenia (which requires a longer duration and often incomplete recovery) and schizophreniform disorder (intermediate duration).', 5),
('f4000000-0000-0000-0000-000000000018', 'A', 'Schizophrenia', false, 'Ruled out because schizophrenia typically involves multiple types of psychotic symptoms (hallucinations, disorganisation, negative symptoms) and more significant functional decline, not this isolated delusion with otherwise preserved functioning.', 1),
('f4000000-0000-0000-0000-000000000018', 'B', 'Normal marital suspicion requiring no diagnosis', false, 'Ruled out because the fixed, unshakeable nature of the belief despite clear contrary evidence, and the resulting obsessive checking behaviour, exceeds normal suspicion and represents a delusional belief.', 2),
('f4000000-0000-0000-0000-000000000018', 'C', 'Delusional disorder (morbid jealousy subtype)', true, 'Correct. A persistent, fixed, non-bizarre delusion (here, of infidelity -- morbid/pathological jealousy) lasting at least one month (here, two years), without other significant psychotic symptoms and with otherwise largely preserved functioning outside the delusional belief system, is characteristic of delusional disorder.', 3),
('f4000000-0000-0000-0000-000000000018', 'D', 'Obsessive-compulsive disorder', false, 'Ruled out because OCD involves ego-dystonic obsessions (recognised by the patient as excessive or irrational) with associated compulsions, whereas this patient holds a fixed, unshakeable belief he considers to be true (a delusion), not an obsession he recognises as irrational.', 4),
('f4000000-0000-0000-0000-000000000018', 'E', 'Bipolar disorder, manic episode', false, 'Ruled out because there is no description of elevated mood, grandiosity or reduced sleep need; the presentation is specifically of an isolated, fixed delusional belief without other manic features.', 5),
('f4000000-0000-0000-0000-000000000019', 'A', 'Metabolic side effects of the antipsychotic medication', true, 'Correct. Second-generation (atypical) antipsychotics, particularly olanzapine and clozapine, carry a significant risk of weight gain, dyslipidaemia and new-onset diabetes; regular metabolic monitoring (weight, glucose, lipids) is recommended for patients on these medications given this well-recognised risk.', 1),
('f4000000-0000-0000-0000-000000000019', 'B', 'Coincidental, unrelated development of type 2 diabetes', false, 'Ruled out because although diabetes can occur independently of medication, olanzapine has a well-established, significant association with metabolic side effects including new-onset diabetes, making this the more likely explanation given the temporal and pharmacological context.', 2),
('f4000000-0000-0000-0000-000000000019', 'C', 'A direct effect of the underlying schizophrenia itself on glucose metabolism', false, $x$Ruled out because although some association between schizophrenia and metabolic risk exists independent of medication, the specific, well-documented and larger effect in this scenario relates to olanzapine's known metabolic side-effect profile.$x$, 3),
('f4000000-0000-0000-0000-000000000019', 'D', 'Simple dietary indiscretion unrelated to medication', false, 'Ruled out because although diet contributes to metabolic health generally, the specific, well-recognised pharmacological effect of olanzapine on weight and glucose metabolism is the more directly relevant explanation here.', 4),
('f4000000-0000-0000-0000-000000000019', 'E', 'A paradoxical effect of reduced psychotic symptoms improving appetite regulation', false, 'Ruled out because this does not reflect the actual, well-documented mechanism; olanzapine has direct metabolic effects (including on appetite and insulin sensitivity) independent of psychiatric symptom improvement.', 5),
('f4000000-0000-0000-0000-000000000020', 'A', 'Positive symptoms', false, 'Ruled out because positive symptoms refer to the presence of abnormal experiences (hallucinations, delusions, disorganised thought/speech), which are explicitly absent in this description; the symptoms here represent an absence or reduction of normal function instead.', 1),
('f4000000-0000-0000-0000-000000000020', 'B', 'Negative symptoms', true, 'Correct. Social withdrawal, flattened (blunted) affect, poverty of speech (alogia) and reduced motivation (avolition) are collectively termed negative symptoms of schizophrenia, reflecting a loss or diminution of normal function, and are often more difficult to treat with antipsychotic medication than positive symptoms.', 2),
('f4000000-0000-0000-0000-000000000020', 'C', 'Cognitive symptoms', false, 'Ruled out because although cognitive impairment (e.g. in memory, attention, executive function) is a recognised separate domain in schizophrenia, the specific symptoms described (affect, speech, motivation, social withdrawal) are classified as negative symptoms, not primarily cognitive.', 3),
('f4000000-0000-0000-0000-000000000020', 'D', 'Catatonic symptoms', false, 'Ruled out because catatonia involves specific motor abnormalities (e.g. stupor, waxy flexibility, mutism, posturing), not this broader pattern of affective flattening, poverty of speech and reduced motivation described as negative symptoms.', 4),
('f4000000-0000-0000-0000-000000000020', 'E', 'Extrapyramidal symptoms', false, 'Ruled out because extrapyramidal symptoms are movement-related side effects of antipsychotic medication (e.g. rigidity, tremor, dystonia), not the illness-related negative symptom domain being described here.', 5),
('f4000000-0000-0000-0000-000000000021', 'A', 'Delirium tremens', true, 'Correct. Acute confusion, agitation, tremor, visual hallucinations and autonomic hyperactivity (tachycardia, hypertension) developing 48-96 hours after alcohol cessation in a person with heavy chronic use is characteristic of delirium tremens, a medical emergency requiring urgent treatment with benzodiazepines and supportive care, including monitoring for seizures.', 1),
('f4000000-0000-0000-0000-000000000021', 'B', 'Simple alcohol withdrawal without delirium', false, 'Ruled out because uncomplicated withdrawal typically causes tremor, anxiety and autonomic symptoms without the confusion and hallucinations described here, which indicate progression to the more severe delirium tremens.', 2),
('f4000000-0000-0000-0000-000000000021', 'C', $x$Wernicke's encephalopathy$x$, false, $x$Ruled out because Wernicke's encephalopathy classically presents with the triad of confusion, ataxia and ophthalmoplegia from thiamine deficiency, not primarily the tremor, autonomic hyperactivity and visual hallucinations described here, though both can coexist in this population and thiamine should always be given.$x$, 3),
('f4000000-0000-0000-0000-000000000021', 'D', 'Acute psychotic episode unrelated to alcohol', false, 'Ruled out because the clear temporal relationship to alcohol cessation in a patient with heavy chronic use, combined with the characteristic autonomic and tremor features, points specifically to delirium tremens rather than a primary psychotic illness.', 4),
('f4000000-0000-0000-0000-000000000021', 'E', 'Hepatic encephalopathy', false, 'Ruled out because although this patient may have underlying liver disease, the specific timing (48-96 hours post-cessation) and combination of tremor with marked autonomic hyperactivity is characteristic of delirium tremens rather than hepatic encephalopathy, which typically has a different clinical pattern (e.g. asterixis, without this degree of autonomic hyperactivity).', 5),
('f4000000-0000-0000-0000-000000000022', 'A', 'Give IV glucose first to correct any hypoglycaemia, then consider thiamine later', false, $x$Ruled out because giving glucose before thiamine in a thiamine-deficient patient can precipitate or worsen Wernicke's encephalopathy; thiamine should be given first (or, if urgent glucose is needed, concurrently).$x$, 1),
('f4000000-0000-0000-0000-000000000022', 'B', 'No specific action needed unless neurological symptoms develop', false, $x$Ruled out because Wernicke's encephalopathy is a preventable complication, and prophylactic thiamine is recommended for at-risk patients before symptoms develop, not reactively only once neurological signs appear.$x$, 2),
('f4000000-0000-0000-0000-000000000022', 'C', 'Start oral thiamine tablets only, as parenteral thiamine has no advantage', false, 'Ruled out because parenteral (IV or IM) thiamine is recommended in at-risk or symptomatic patients, as oral absorption may be unreliable, particularly in this higher-risk population.', 3),
('f4000000-0000-0000-0000-000000000022', 'D', 'Delay any thiamine until formal cognitive testing has been completed', false, 'Ruled out because thiamine should be given promptly to at-risk patients as a preventive measure, not delayed pending further testing, given the risk of precipitating irreversible neurological damage.', 4),
('f4000000-0000-0000-0000-000000000022', 'E', 'Administer IV thiamine before giving any glucose-containing fluids or nutrition', true, $x$Correct. In patients with chronic alcohol misuse and poor nutrition (at risk of thiamine deficiency), IV thiamine should be given before any glucose-containing fluids or nutrition, as glucose administration can precipitate or worsen Wernicke's encephalopathy by consuming remaining thiamine stores in glucose metabolism.$x$, 5),
('f4000000-0000-0000-0000-000000000023', 'A', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease causes a more global, progressive cognitive decline across multiple domains, not this specific, relatively isolated memory deficit with confabulation following an episode of Wernicke's encephalopathy.$x$, 1),
('f4000000-0000-0000-0000-000000000023', 'B', 'Delirium tremens', false, 'Ruled out because delirium tremens is an acute, fluctuating confusional state occurring during alcohol withdrawal, not this persistent, stable memory deficit occurring months after the acute episode has resolved.', 2),
('f4000000-0000-0000-0000-000000000023', 'C', 'Normal age-related memory decline', false, $x$Ruled out because the severity and specific pattern (confabulation, severe anterograde amnesia) following a clear preceding episode of Wernicke's encephalopathy is a recognised specific syndrome (Korsakoff), not simply normal ageing.$x$, 3),
('f4000000-0000-0000-0000-000000000023', 'D', 'Korsakoff syndrome', true, $x$Correct. A persistent, severe anterograde (and often retrograde) amnesia with confabulation, following an episode of Wernicke's encephalopathy, with relative preservation of other cognitive domains, is characteristic of Korsakoff syndrome, a chronic and often irreversible complication of untreated or inadequately treated thiamine deficiency.$x$, 4),
('f4000000-0000-0000-0000-000000000023', 'E', 'Vascular dementia', false, $x$Ruled out because vascular dementia typically shows a stepwise decline related to cerebrovascular events, not this specific memory and confabulation pattern following thiamine deficiency-related Wernicke's encephalopathy.$x$, 5),
('f4000000-0000-0000-0000-000000000024', 'A', 'Administer flumazenil', false, 'Ruled out because flumazenil reverses benzodiazepine, not opioid, effects; it would not address the underlying opioid toxicity causing this presentation.', 1),
('f4000000-0000-0000-0000-000000000024', 'B', 'Administer naloxone and provide ventilatory support', true, 'Correct. Pinpoint pupils, severe respiratory depression and reduced consciousness in the context of opioid use is characteristic of opioid overdose, a life-threatening emergency; naloxone (an opioid receptor antagonist) should be given promptly, alongside airway management and ventilatory support, to rapidly reverse the respiratory depression.', 2),
('f4000000-0000-0000-0000-000000000024', 'C', 'Administer activated charcoal', false, 'Ruled out because activated charcoal is used for certain oral overdoses within a specific time window, not for IV opioid overdose, and does not address the immediate life-threatening respiratory depression, which requires naloxone.', 3),
('f4000000-0000-0000-0000-000000000024', 'D', 'Simply observe without active intervention', false, 'Ruled out because this represents a life-threatening emergency (severe respiratory depression) requiring immediate active reversal with naloxone, not passive observation.', 4),
('f4000000-0000-0000-0000-000000000024', 'E', 'Administer high-flow oxygen alone, without naloxone', false, 'Ruled out because although supporting oxygenation is important, naloxone specifically reverses the underlying opioid-induced respiratory depression and should be given promptly alongside airway/ventilatory support, not omitted.', 5),
('f4000000-0000-0000-0000-000000000025', 'A', 'Naloxone as maintenance therapy', false, 'Ruled out because naloxone is an opioid antagonist used to reverse overdose, not a maintenance substitution therapy; it would precipitate withdrawal rather than stabilise the patient.', 1),
('f4000000-0000-0000-0000-000000000025', 'B', 'High-dose benzodiazepines as substitution therapy', false, 'Ruled out because benzodiazepines are not used as substitution therapy for opioid dependence and carry their own dependence and overdose risks, particularly in combination with opioids.', 2),
('f4000000-0000-0000-0000-000000000025', 'C', 'Methadone or buprenorphine', true, 'Correct. Methadone (a full opioid agonist) and buprenorphine (a partial agonist) are the two main first-line options for opioid substitution therapy, aiming to reduce withdrawal symptoms and cravings, stabilise the patient, and reduce the risks associated with illicit opioid use (overdose, injecting-related harm, criminal activity).', 3),
('f4000000-0000-0000-0000-000000000025', 'D', 'Antipsychotic medication as first-line treatment', false, 'Ruled out because antipsychotics have no role in opioid substitution therapy; they are used for psychotic disorders, not opioid dependence management.', 4),
('f4000000-0000-0000-0000-000000000025', 'E', 'No pharmacological treatment; psychological therapy alone is standard first-line', false, 'Ruled out because opioid substitution therapy (methadone or buprenorphine) alongside psychosocial support is standard evidence-based first-line management for opioid dependence, not psychological therapy in isolation.', 5),
('f4000000-0000-0000-0000-000000000026', 'A', 'Methadone has no cardiac effects and the antibiotic alone is responsible, unrelated to methadone', false, 'Ruled out because methadone itself is independently and well-recognised to cause QT prolongation, and the interaction with certain other QT-prolonging drugs is a specific, important safety consideration, not an isolated effect of the antibiotic alone.', 1),
('f4000000-0000-0000-0000-000000000026', 'B', 'Methadone is associated with dose-dependent QT prolongation, and interacting drugs further increase torsades de pointes risk', true, 'Correct. Methadone is well-recognised to cause dose-dependent QT interval prolongation, increasing the risk of torsades de pointes; certain antibiotics (and other drugs) can further prolong the QT interval or inhibit methadone metabolism, compounding this risk, making ECG monitoring and careful medication review important in patients on methadone.', 2),
('f4000000-0000-0000-0000-000000000026', 'C', 'This represents a normal, expected effect requiring no further action', false, 'Ruled out because a markedly prolonged QT interval carries a genuine risk of life-threatening arrhythmia (torsades de pointes) and requires active assessment and management, not being disregarded as normal.', 3),
('f4000000-0000-0000-0000-000000000026', 'D', 'Methadone should be stopped abruptly with no arrangement for alternative treatment', false, 'Ruled out because abrupt cessation of methadone risks precipitating withdrawal and return to illicit opioid use; any changes should be made carefully, addressing the interacting medication and considering dose adjustment or ECG monitoring rather than abrupt discontinuation.', 4),
('f4000000-0000-0000-0000-000000000026', 'E', 'QT prolongation with methadone is only a concern in patients with pre-existing structural heart disease', false, 'Ruled out because methadone-associated QT prolongation is a recognised risk even without underlying structural heart disease, particularly relevant with interacting drugs or at higher methadone doses.', 5),
('f4000000-0000-0000-0000-000000000027', 'A', 'Alcohol-related liver disease', true, 'Correct. An AST:ALT ratio greater than 2:1, combined with a markedly raised gamma-GT (a sensitive, though non-specific, marker of alcohol use), is a classic biochemical pattern of alcohol-related liver disease, distinguishing it from most other causes of liver dysfunction, which typically show ALT predominance.', 1),
('f4000000-0000-0000-0000-000000000027', 'B', 'Viral hepatitis', false, 'Ruled out because viral hepatitis typically causes an ALT-predominant pattern (AST:ALT ratio less than 1), the opposite pattern to that described here, which is more specific to alcohol-related liver injury.', 2),
('f4000000-0000-0000-0000-000000000027', 'C', 'Non-alcoholic fatty liver disease', false, 'Ruled out because NAFLD typically also shows an ALT-predominant pattern, unlike the AST-predominant pattern with markedly raised gamma-GT specifically associated with alcohol-related liver disease.', 3),
('f4000000-0000-0000-0000-000000000027', 'D', 'Drug-induced liver injury from paracetamol', false, 'Ruled out because paracetamol-induced liver injury typically causes a markedly raised ALT (often very high, reflecting hepatocellular necrosis) rather than this specific AST-predominant pattern with raised gamma-GT.', 4),
('f4000000-0000-0000-0000-000000000027', 'E', 'Autoimmune hepatitis', false, 'Ruled out because autoimmune hepatitis typically shows an ALT-predominant pattern with specific autoantibodies, not the classic alcohol-related AST:ALT ratio and gamma-GT pattern described here.', 5),
('f4000000-0000-0000-0000-000000000028', 'A', 'Heroin', false, 'Ruled out because heroin (an opioid) causes pinpoint pupils and respiratory depression, the opposite sympathomimetic picture to the dilated pupils, tachycardia and hypertension described here.', 1),
('f4000000-0000-0000-0000-000000000028', 'B', 'Cannabis', false, 'Ruled out because although cannabis can cause tachycardia and anxiety, it does not typically cause this severity of sympathomimetic toxicity with hypertension and chest pain from coronary vasospasm.', 2),
('f4000000-0000-0000-0000-000000000028', 'C', 'Cocaine', true, 'Correct. Severe agitation, dilated pupils, tachycardia, hypertension and chest pain (from coronary vasospasm and increased myocardial oxygen demand) together represent a sympathomimetic toxidrome, classically caused by cocaine, which inhibits reuptake of catecholamines (noradrenaline, dopamine, serotonin), producing marked sympathetic overactivity.', 3),
('f4000000-0000-0000-0000-000000000028', 'D', 'Benzodiazepines', false, 'Ruled out because benzodiazepines cause sedation and reduced sympathetic activity, the opposite of the agitation and sympathomimetic features described here.', 4),
('f4000000-0000-0000-0000-000000000028', 'E', 'Alcohol', false, 'Ruled out because acute alcohol intoxication typically causes sedation and reduced sympathetic tone (at least initially), not this pattern of marked sympathomimetic overactivity with chest pain.', 5),
('f4000000-0000-0000-0000-000000000029', 'A', 'Abrupt cessation, as benzodiazepines can be safely stopped suddenly', false, 'Ruled out because abrupt cessation after long-term, high-dose use carries a significant risk of severe withdrawal, including seizures, and is not considered safe practice.', 1),
('f4000000-0000-0000-0000-000000000029', 'B', 'Switching immediately to an opioid to manage withdrawal symptoms', false, 'Ruled out because opioids do not appropriately manage benzodiazepine withdrawal and introduce a separate substance dependence risk; gradual benzodiazepine tapering (sometimes via conversion to a longer-acting benzodiazepine) is the appropriate approach.', 2),
('f4000000-0000-0000-0000-000000000029', 'C', 'No specific plan needed, as benzodiazepine dependence resolves spontaneously', false, 'Ruled out because benzodiazepine dependence, particularly after long-term high-dose use, requires an active, structured tapering plan rather than being expected to resolve without any specific approach.', 3),
('f4000000-0000-0000-0000-000000000029', 'D', 'Increasing the dose further before considering any reduction', false, 'Ruled out because increasing the dose would worsen dependence rather than support safe discontinuation; a gradual reduction plan is the appropriate approach.', 4),
('f4000000-0000-0000-0000-000000000029', 'E', 'Gradual, supervised dose reduction (tapering) rather than abrupt cessation', true, 'Correct. Long-term, high-dose benzodiazepine use requires gradual, supervised dose tapering rather than abrupt cessation, as sudden withdrawal carries a significant risk of severe withdrawal symptoms, including seizures, which can be life-threatening.', 5),
('f4000000-0000-0000-0000-000000000030', 'A', 'No formal assessment is needed; simply advise him to stop drinking entirely', false, 'Ruled out because a structured assessment helps quantify risk and guide an appropriately tailored response, rather than jumping to a blanket recommendation without first understanding the pattern and level of risk.', 1),
('f4000000-0000-0000-0000-000000000030', 'B', 'Refer directly to specialist addiction services without any initial assessment', false, 'Ruled out because most alcohol-related concerns identified in primary care or general settings are appropriately managed with brief intervention following screening; specialist referral is reserved for more severe dependence or complex cases identified through this initial assessment.', 2),
('f4000000-0000-0000-0000-000000000030', 'C', 'Order liver function tests as the sole method of assessing his alcohol use', false, 'Ruled out because liver function tests can be normal despite significant alcohol consumption, and are not a sensitive standalone method for assessing drinking patterns; a structured history/questionnaire-based assessment is the appropriate initial approach.', 3),
('f4000000-0000-0000-0000-000000000030', 'D', 'Use a validated screening tool such as AUDIT (Alcohol Use Disorders Identification Test)', true, 'Correct. A validated, structured screening tool such as AUDIT allows systematic assessment of alcohol consumption and related problems, helping identify hazardous, harmful or dependent drinking patterns and guiding whether brief intervention or further specialist referral is needed.', 4),
('f4000000-0000-0000-0000-000000000030', 'E', 'Dismiss the disclosure as not requiring any follow-up, since he has not reported symptoms', false, 'Ruled out because proactively screening for alcohol use, even in the absence of overt symptoms or problems, is good practice for early identification of hazardous or harmful drinking patterns.', 5),
('f4000000-0000-0000-0000-000000000031', 'A', 'Formally assess his capacity to make this specific decision, and if he lacks capacity, proceed in his best interests', true, 'Correct. Capacity is decision-specific and must be formally assessed for the particular decision at hand (here, surgery); if he is found to lack capacity for this decision (unable to understand, retain, weigh the information, or communicate a decision), treatment decisions should be made in his best interests, involving family/carers and following the appropriate legal framework.', 1),
('f4000000-0000-0000-0000-000000000031', 'B', 'Automatically defer to his refusal, as all patients have an absolute right to refuse treatment regardless of capacity', false, 'Ruled out because although patients with capacity have the right to refuse treatment even if the decision seems unwise, this right applies only when the patient has capacity for that specific decision; his apparent inability to retain or understand key information raises a genuine question about his capacity that must be formally assessed first.', 2),
('f4000000-0000-0000-0000-000000000031', 'C', 'Assume he lacks capacity for all decisions because of his dementia diagnosis alone', false, 'Ruled out because a diagnosis of dementia does not automatically mean a person lacks capacity for all decisions; capacity must be assessed specifically for each individual decision, as capacity can fluctuate and vary by decision complexity.', 3),
('f4000000-0000-0000-0000-000000000031', 'D', 'Proceed with surgery immediately without any capacity assessment or best interests process', false, $x$Ruled out because proceeding with treatment against a patient's expressed wishes requires proper capacity assessment and, if he lacks capacity, a best interests decision-making process, not simply overriding his refusal without following this process.$x$, 4),
('f4000000-0000-0000-0000-000000000031', 'E', 'Ask his family to make the decision on his behalf without any capacity assessment', false, 'Ruled out because a formal capacity assessment for the specific decision must be undertaken first; family involvement is part of best interests decision-making, but only after capacity has been properly assessed and found to be lacking.', 5),
('f4000000-0000-0000-0000-000000000032', 'A', 'The Mental Capacity Act alone, as this only concerns his capacity to consent to admission', false, 'Ruled out because although capacity is relevant, when the core issue is risk arising from a treatable mental disorder and the person is refusing psychiatric treatment for that disorder, the Mental Health Act (not the Mental Capacity Act) is the primary framework specifically designed for this situation, regardless of his capacity status in other areas.', 1),
('f4000000-0000-0000-0000-000000000032', 'B', 'No legal framework is needed; he can simply be persuaded informally', false, 'Ruled out because given the significant risk and his refusal of voluntary treatment, informal persuasion alone is not sufficient; a formal legal framework (Mental Health Act assessment) is needed to ensure both his safety and his legal rights are properly protected.', 2),
('f4000000-0000-0000-0000-000000000032', 'C', 'Police detention under criminal law', false, 'Ruled out because this is a mental health treatment issue, not a criminal matter; the appropriate framework is a mental health-specific legal process (Mental Health Act), not criminal detention.', 3),
('f4000000-0000-0000-0000-000000000032', 'D', 'Automatic admission without formal assessment, given the severity described', false, 'Ruled out because even in urgent situations, a proper assessment process (involving appropriately qualified professionals) is required under the Mental Health Act before formal detention, rather than automatic admission without any structured assessment.', 4),
('f4000000-0000-0000-0000-000000000032', 'E', 'Assessment and possible detention under the Mental Health Act', true, 'Correct. When a person has a mental disorder of a nature or degree warranting hospital assessment/treatment, and there is significant risk to their health, safety, or the safety of others, and they are unwilling to accept voluntary admission, the Mental Health Act provides the legal framework for involuntary assessment and treatment specifically for the mental disorder.', 5),
('f4000000-0000-0000-0000-000000000033', 'A', 'Both Acts are functionally identical and interchangeable in all situations', false, 'Ruled out because these are distinct legal frameworks with different purposes, criteria and scopes, not interchangeable, and correctly identifying which applies is important for both legal compliance and appropriate patient care.', 1),
('f4000000-0000-0000-0000-000000000033', 'B', 'The Mental Capacity Act can only be used for physical health decisions, never mental health treatment', false, 'Ruled out because the Mental Capacity Act can apply to mental health treatment decisions too, in situations where the Mental Health Act criteria are not met (e.g. a person lacking capacity due to a condition other than the specific mental disorder criteria required for the Mental Health Act) -- the distinction is more nuanced than a simple physical/mental health divide.', 2),
('f4000000-0000-0000-0000-000000000033', 'C', 'The Mental Health Act requires the patient to lack capacity before it can be used', false, 'Ruled out because a key feature of the Mental Health Act is that it can be used even when a patient has capacity to refuse treatment for their mental disorder, provided the specific legal criteria relating to risk and the nature/degree of the disorder are met.', 3),
('f4000000-0000-0000-0000-000000000033', 'D', 'The Mental Health Act can be used regardless of capacity, when treatment for a mental disorder is needed due to risk, whereas the Mental Capacity Act applies when a person lacks capacity for a specific decision (of any kind) and requires it to be made in their best interests', true, 'Correct. The Mental Health Act allows treatment for a mental disorder even if the person has capacity to refuse it, provided the legal criteria (risk, nature/degree of disorder) are met, whereas the Mental Capacity Act applies broadly to any decision where a person lacks capacity, requiring decisions to be made in their best interests, and is not specific to mental disorder treatment.', 4),
('f4000000-0000-0000-0000-000000000033', 'E', 'Neither Act has any role in involuntary treatment decisions', false, 'Ruled out because both Acts provide distinct legal frameworks that can, in different circumstances, support involuntary treatment decisions when their respective specific criteria are met.', 5),
('f4000000-0000-0000-0000-000000000034', 'A', 'No rights are retained once a patient is detained', false, 'Ruled out because detention under the Mental Health Act does not remove all patient rights; specific important legal safeguards, including the right to appeal, are explicitly retained and are a core part of the legal framework.', 1),
('f4000000-0000-0000-0000-000000000034', 'B', 'The right to refuse all medication indefinitely, regardless of detention status', false, $x$Ruled out because although consent and capacity remain relevant considerations that inform treatment decisions, detention under the Mental Health Act can, within specific legal safeguards, permit treatment for the mental disorder even against the patient's wishes in certain circumstances, distinguishing it from an absolute, indefinite right to refuse all treatment.$x$, 2),
('f4000000-0000-0000-0000-000000000034', 'C', 'The right to appeal against detention, including to a Mental Health Tribunal', true, $x$Correct. Patients detained under the Mental Health Act retain important legal rights, including the right to appeal against their detention (e.g. to a Mental Health Tribunal or hospital managers' hearing), access to independent mental health advocacy, and the right to have their detention regularly reviewed, ensuring appropriate legal safeguards even while detained.$x$, 3),
('f4000000-0000-0000-0000-000000000034', 'D', 'The right to discharge themselves at any time without any formal process', false, 'Ruled out because a key feature of detention under the Mental Health Act is precisely that the patient cannot simply discharge themselves at will; formal processes (including appeal rights) exist instead, reflecting the balance between patient rights and clinical/risk considerations.', 4),
('f4000000-0000-0000-0000-000000000034', 'E', 'The right to prevent any review of their detention status', false, $x$Ruled out because regular review of detention is a required legal safeguard, not something the patient can prevent; this regular review process actually protects the patient's rights, rather than being something to avoid.$x$, 5),
('f4000000-0000-0000-0000-000000000035', 'A', 'Automatically respect her refusal, as she is an adult stating a clear preference', false, 'Ruled out because although patient autonomy is important, if her illness is genuinely impairing her capacity to weigh information about this specific, life-threatening decision, her refusal cannot simply be accepted without proper capacity assessment, given the significant risk involved.', 1),
('f4000000-0000-0000-0000-000000000035', 'B', 'Consider that her illness may be impairing her capacity to weigh information about treatment, warranting further formal capacity assessment and, if needed, an appropriate legal framework for treatment', true, $x$Correct. Severe eating disorders can significantly impair a person's ability to weigh information about their condition and treatment, even while other cognitive functions appear intact; if formal assessment confirms she lacks capacity for this specific decision due to her illness, and there is significant risk, an appropriate legal framework (potentially the Mental Health Act, given this relates to treatment of a mental disorder) should be considered to ensure safe treatment.$x$, 2),
('f4000000-0000-0000-0000-000000000035', 'C', 'Assume she has capacity because she can clearly articulate her refusal', false, 'Ruled out because being able to communicate a decision is only one of the elements required for capacity; the ability to understand, retain and, crucially, weigh the relevant information must also be intact, and eating disorders can specifically impair this weighing element even when communication seems clear.', 3),
('f4000000-0000-0000-0000-000000000035', 'D', 'Discharge her from care with no further follow-up, as she has declined treatment', false, 'Ruled out because given the significant risk (dangerously low BMI) and question over her capacity for this decision, discharge without further assessment and appropriate action would not meet the required standard of care.', 4),
('f4000000-0000-0000-0000-000000000035', 'E', 'Proceed with involuntary treatment immediately without any capacity assessment', false, 'Ruled out because a proper, formal capacity assessment for this specific decision should be undertaken as part of the appropriate process, rather than skipping directly to involuntary treatment without this structured assessment step.', 5),
('f4000000-0000-0000-0000-000000000036', 'A', 'His ability to understand the information', false, 'Ruled out because being able to repeat the information back suggests at least superficial understanding/retention is present; the specific deficit described is in using/weighing this information to reach a decision, not basic understanding or retention.', 1),
('f4000000-0000-0000-0000-000000000036', 'B', 'His ability to use or weigh the information as part of the decision-making process', true, $x$Correct. The capacity test requires a person to understand, retain, use/weigh the information as part of the decision-making process, and communicate their decision; being able to simply repeat information back (retention) without being able to relate it to their own situation and weigh it to reach a reasoned decision indicates a specific impairment in the 'use or weigh' element.$x$, 2),
('f4000000-0000-0000-0000-000000000036', 'C', 'His ability to retain the information', false, 'Ruled out because retention is demonstrated by his ability to repeat the information back; the impairment described is specifically in the subsequent step of using/weighing that retained information.', 3),
('f4000000-0000-0000-0000-000000000036', 'D', 'His ability to communicate a decision', false, 'Ruled out because there is no indication he is unable to communicate; the specific deficit described relates to the reasoning/weighing process, not the ability to express a decision.', 4),
('f4000000-0000-0000-0000-000000000036', 'E', 'There is no impairment in any element of his capacity', false, $x$Ruled out because the scenario specifically describes a deficit in relating information to his own circumstances and reasoning towards a decision, which represents a genuine impairment in the 'use or weigh' element of the capacity test.$x$, 5),
('f4000000-0000-0000-0000-000000000037', 'A', 'A person should be presumed to lack capacity if their decision seems unwise', false, 'Ruled out because making an unwise decision does not, by itself, indicate a lack of capacity; the presumption of capacity applies regardless of whether others agree with the decision being made.', 1),
('f4000000-0000-0000-0000-000000000037', 'B', 'Capacity should be assumed to be absent in anyone with a psychiatric diagnosis', false, 'Ruled out because a psychiatric (or any other) diagnosis does not automatically mean a person lacks capacity; each specific decision requires individual assessment, starting from the presumption of capacity.', 2),
('f4000000-0000-0000-0000-000000000037', 'C', $x$Capacity assessment should only be performed if requested by the patient's family$x$, false, $x$Ruled out because capacity assessment is triggered by a genuine question or doubt about a person's ability to make a specific decision, based on clinical judgement, not solely upon family request.$x$, 3),
('f4000000-0000-0000-0000-000000000037', 'D', 'Capacity is a fixed, permanent state that, once assessed, never needs to be reconsidered', false, 'Ruled out because capacity is decision-specific and can fluctuate over time or with different types of decisions; it should be reassessed as relevant, not treated as a permanently fixed status from a single assessment.', 4),
('f4000000-0000-0000-0000-000000000037', 'E', 'A person is presumed to have capacity unless it is established that they lack it', true, 'Correct. A fundamental principle of capacity law is that every adult is presumed to have capacity to make their own decisions unless it is established, through proper assessment, that they lack capacity for that specific decision; capacity should never be assumed to be absent simply based on diagnosis, age, appearance, or an unwise decision.', 5),
('f4000000-0000-0000-0000-000000000038', 'A', 'Proceed with the decision without seeking any additional input, since no family is available', false, 'Ruled out because the absence of family specifically triggers the need for an IMCA, rather than being a reason to proceed without any additional independent input into the best interests process.', 1),
('f4000000-0000-0000-0000-000000000038', 'B', 'Delay the decision indefinitely until family can be located', false, 'Ruled out because for necessary treatment decisions, an IMCA can be arranged relatively promptly to support the best interests process, rather than indefinitely delaying potentially necessary treatment while searching for family who may not exist or be traceable.', 2),
('f4000000-0000-0000-0000-000000000038', 'C', 'Ask a member of the clinical team to act informally as her advocate', false, $x$Ruled out because the IMCA role is specifically designed to be independent of the treating team, providing an impartial voice for the patient's interests, which an internal team member cannot adequately replicate.$x$, 3),
('f4000000-0000-0000-0000-000000000038', 'D', 'Arrange for an Independent Mental Capacity Advocate (IMCA) to be involved', true, $x$Correct. When a person lacks capacity for a significant decision (such as serious medical treatment) and has no family or friends appropriate to consult, an Independent Mental Capacity Advocate should be involved to represent the person's views, wishes and interests as part of the best interests decision-making process.$x$, 4),
('f4000000-0000-0000-0000-000000000038', 'E', 'Refer the decision to the police for resolution', false, 'Ruled out because this is a medical treatment and best interests decision-making matter, not a police/criminal justice issue.', 5),
('f4000000-0000-0000-0000-000000000039', 'A', 'Override the advance decision and give the transfusion, since he is now unconscious and cannot object in the moment', false, 'Ruled out because a valid and applicable advance decision remains legally binding even when the person can no longer express their wishes in the moment; this is precisely the situation such decisions are designed to address.', 1),
('f4000000-0000-0000-0000-000000000039', 'B', 'Ask his family to override his previously stated wishes', false, $x$Ruled out because family members cannot override a patient's own valid and applicable advance decision; the decision reflects the patient's own autonomous choice made while he had capacity.$x$, 2),
('f4000000-0000-0000-0000-000000000039', 'C', 'Respect his valid and applicable advance decision to refuse blood transfusion, even though this may result in his death', true, $x$Correct. A valid and applicable advance decision to refuse specific treatment, made while the person had capacity, must be respected even if this results in the person's death, once it is confirmed to be valid (properly made, not withdrawn) and applicable to the current circumstances (the specific treatment and situation anticipated).$x$, 3),
('f4000000-0000-0000-0000-000000000039', 'D', 'Assume the advance decision is automatically invalid because he is now critically unwell', false, 'Ruled out because being critically unwell and unconscious does not itself invalidate an advance decision; this is exactly the situation such decisions anticipate, provided it remains valid and applicable to the current circumstances.', 4),
('f4000000-0000-0000-0000-000000000039', 'E', 'Give the transfusion regardless, as preserving life always takes precedence over any prior wishes', false, $x$Ruled out because respecting a valid and applicable advance decision to refuse treatment, even when this may result in death, reflects a fundamental principle of patient autonomy in medical law and ethics, and does not automatically defer to preserving life over the person's clearly expressed wishes.$x$, 5),
('f4000000-0000-0000-0000-000000000040', 'A', 'A formal Mental Health Act assessment (or use of an appropriate short-term holding power pending full assessment) must be carried out before she can be legally prevented from leaving', true, 'Correct. An informally admitted patient retains the right to leave hospital at any time, as they have not been detained under any legal framework; if the team believes there is significant risk requiring her to be prevented from leaving, an appropriate short-term holding power can be used to allow time for a formal Mental Health Act assessment, but she cannot simply be prevented from leaving without following this proper legal process.', 1),
('f4000000-0000-0000-0000-000000000040', 'B', $x$She can simply be physically prevented from leaving, given the team's clinical concern about risk$x$, false, 'Ruled out because clinical concern alone, without following the appropriate legal process (holding power and/or formal assessment), does not give staff the legal authority to physically prevent an informal patient from leaving; this would breach her legal rights.', 2),
('f4000000-0000-0000-0000-000000000040', 'C', 'Her family can legally authorise her continued detention on the ward', false, 'Ruled out because family members do not have the legal authority to authorise detention; this requires the formal Mental Health Act process involving appropriately qualified professionals.', 3),
('f4000000-0000-0000-0000-000000000040', 'D', 'No action is possible, and she must be allowed to leave immediately regardless of risk', false, 'Ruled out because appropriate legal mechanisms (such as short-term holding powers, pending full Mental Health Act assessment) exist specifically to manage this situation when there is genuine, significant risk, rather than there being no options available.', 4),
('f4000000-0000-0000-0000-000000000040', 'E', 'The police must be called to arrest her for wanting to leave', false, 'Ruled out because this is a healthcare and mental health legal framework issue, not a criminal matter; the appropriate response involves mental health legislation, not police arrest.', 5),
('f4000000-0000-0000-0000-000000000041', 'A', 'Generalised anxiety disorder', true, 'Correct. Persistent, excessive, difficult-to-control worry about multiple life domains, present for at least six months, with associated physical and cognitive symptoms (muscle tension, restlessness, poor concentration, sleep disturbance), is characteristic of generalised anxiety disorder.', 1),
('f4000000-0000-0000-0000-000000000041', 'B', 'Panic disorder', false, 'Ruled out because panic disorder is characterised by recurrent, discrete panic attacks with intense acute symptoms, not this pattern of persistent, pervasive worry across multiple areas of life.', 2),
('f4000000-0000-0000-0000-000000000041', 'C', 'Specific phobia', false, 'Ruled out because a specific phobia involves marked, circumscribed fear of a particular object or situation, not the generalised, multi-domain worry described here.', 3),
('f4000000-0000-0000-0000-000000000041', 'D', 'Obsessive-compulsive disorder', false, 'Ruled out because OCD involves specific intrusive obsessions with associated compulsions, not this pattern of generalised, free-floating worry across multiple life areas without described compulsive behaviours.', 4),
('f4000000-0000-0000-0000-000000000041', 'E', 'Adjustment disorder', false, 'Ruled out because adjustment disorder occurs in response to a specific identifiable stressor, whereas GAD involves pervasive worry across multiple domains, not necessarily tied to a single identifiable stressor.', 5),
('f4000000-0000-0000-0000-000000000042', 'A', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves persistent, pervasive worry without the discrete, acute panic attacks described here; this presentation is specific to episodic panic.', 1),
('f4000000-0000-0000-0000-000000000042', 'B', 'Social anxiety disorder', false, 'Ruled out because although he has become anxious about public places, the core presentation is of discrete, spontaneous panic attacks (panic disorder), rather than a primary fear specifically of social scrutiny or embarrassment in social situations.', 2),
('f4000000-0000-0000-0000-000000000042', 'C', 'Myocardial infarction', false, 'Ruled out because although the physical symptoms overlap, the recurrent, self-limiting, discrete nature of the episodes, occurring in a young patient without cardiac risk factors, is far more consistent with panic disorder; cardiac causes should still be appropriately excluded when relevant, but the pattern described is classic for panic disorder.', 3),
('f4000000-0000-0000-0000-000000000042', 'D', 'Panic disorder', true, 'Correct. Recurrent, unexpected panic attacks (discrete episodes of intense fear peaking within minutes, with characteristic physical symptoms and fear of dying/losing control), together with persistent worry about having further attacks, is characteristic of panic disorder.', 4),
('f4000000-0000-0000-0000-000000000042', 'E', 'Hyperthyroidism', false, 'Ruled out because although hyperthyroidism can cause anxiety symptoms, the specific, discrete, episodic pattern with peak intensity within minutes is more characteristic of panic attacks; thyroid function would typically be checked to exclude this as a contributing/alternative cause.', 5),
('f4000000-0000-0000-0000-000000000043', 'A', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves pervasive worry across multiple life domains, not this specific, circumscribed fear focused on social/performance situations and fear of judgement.', 1),
('f4000000-0000-0000-0000-000000000043', 'B', 'Agoraphobia', false, 'Ruled out because agoraphobia involves fear of situations where escape might be difficult or help unavailable (e.g. crowds, open spaces, public transport), rather than the specific fear of social scrutiny and judgement described here.', 2),
('f4000000-0000-0000-0000-000000000043', 'C', 'Specific phobia (simple phobia)', false, 'Ruled out because specific phobia involves fear of a particular object or situation (e.g. animals, heights), not this broader pattern of fear across multiple social and performance situations driven by fear of judgement.', 3),
('f4000000-0000-0000-0000-000000000043', 'D', 'Panic disorder', false, 'Ruled out because although physical anxiety symptoms occur, the core feature here is a specific, persistent fear of social scrutiny and judgement across various situations, rather than recurrent, unexpected panic attacks as the primary presentation.', 4),
('f4000000-0000-0000-0000-000000000043', 'E', 'Social anxiety disorder (social phobia)', true, 'Correct. Marked, persistent fear of social or performance situations due to fear of scrutiny, judgement or embarrassment, with associated avoidance and significant functional impairment, is characteristic of social anxiety disorder.', 5),
('f4000000-0000-0000-0000-000000000044', 'A', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves diffuse worry about real-life concerns, not the specific, ego-dystonic, intrusive obsessions with associated ritualistic compulsions described here.', 1),
('f4000000-0000-0000-0000-000000000044', 'B', 'Obsessive-compulsive disorder', true, 'Correct. Recurrent, intrusive, ego-dystonic obsessions (recognised by the patient as excessive/irrational, causing distress) combined with compulsions (repetitive behaviours performed to reduce the anxiety generated by the obsessions), causing significant functional impairment, defines obsessive-compulsive disorder.', 2),
('f4000000-0000-0000-0000-000000000044', 'C', 'Delusional disorder', false, 'Ruled out because in OCD, the person recognises the thoughts as excessive/irrational (ego-dystonic), unlike a delusion, which is held with conviction as true; this insight is a key distinguishing feature.', 3),
('f4000000-0000-0000-0000-000000000044', 'D', 'Specific phobia', false, 'Ruled out because a specific phobia involves fear of a particular external object or situation without the internally generated, intrusive obsessional thoughts and associated compulsive rituals characteristic of OCD.', 4),
('f4000000-0000-0000-0000-000000000044', 'E', 'Body dysmorphic disorder', false, 'Ruled out because BDD involves preoccupation with perceived flaws in physical appearance, not the contamination-focused obsessions and washing compulsions described here.', 5),
('f4000000-0000-0000-0000-000000000045', 'A', 'Acute stress reaction', false, 'Ruled out because acute stress reaction describes symptoms occurring within the first month after trauma and typically resolving within days to weeks; this presentation, persisting at three months with the full symptom cluster, meets criteria for PTSD instead.', 1),
('f4000000-0000-0000-0000-000000000045', 'B', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves pervasive worry not specifically tied to re-experiencing a traumatic event, avoidance of trauma reminders, or the specific hyperarousal and numbing symptom clusters characteristic of PTSD.', 2),
('f4000000-0000-0000-0000-000000000045', 'C', 'Post-traumatic stress disorder', true, 'Correct. Re-experiencing symptoms (flashbacks, nightmares), avoidance of trauma-related stimuli, hyperarousal (hypervigilance, exaggerated startle response), and emotional numbing/withdrawal, persisting beyond one month following exposure to a traumatic event, together define post-traumatic stress disorder.', 3),
('f4000000-0000-0000-0000-000000000045', 'D', 'Major depressive disorder alone', false, 'Ruled out because although emotional numbing and withdrawal can overlap with depression, the specific presence of flashbacks, trauma-related avoidance and hyperarousal symptoms points to PTSD as the primary diagnosis, though depression can coexist.', 4),
('f4000000-0000-0000-0000-000000000045', 'E', 'Specific phobia (of cars)', false, 'Ruled out because although he avoids driving, the full symptom picture (flashbacks, hyperarousal, emotional numbing) extends well beyond a simple, isolated phobic avoidance pattern, indicating PTSD rather than a specific phobia alone.', 5),
('f4000000-0000-0000-0000-000000000046', 'A', 'Somatic symptom disorder', true, 'Correct. Persistent, distressing physical symptoms, disproportionate and excessive thoughts, feelings or behaviours related to the symptoms (health-related anxiety, high symptom-related distress, excessive time/energy devoted to symptoms), causing significant functional impairment over an extended period, is characteristic of somatic symptom disorder, regardless of whether an organic cause is fully excluded.', 1),
('f4000000-0000-0000-0000-000000000046', 'B', 'Malingering', false, 'Ruled out because malingering involves conscious, deliberate fabrication of symptoms for external gain (e.g. financial compensation, avoiding work), which is a different concept from the genuine distress and symptom experience described in somatic symptom disorder.', 2),
('f4000000-0000-0000-0000-000000000046', 'C', 'Factitious disorder', false, 'Ruled out because factitious disorder involves consciously producing or feigning symptoms for internal psychological gain (adopting the sick role), which differs from the genuine, unintentional symptom experience and distress characteristic of somatic symptom disorder.', 3),
('f4000000-0000-0000-0000-000000000046', 'D', 'Conversion disorder (functional neurological symptom disorder) specifically', false, 'Ruled out because conversion disorder involves specific neurological symptoms (e.g. weakness, seizures) inconsistent with recognised neurological disease, whereas this presentation involves multiple, varied physical symptoms across different systems, better characterised by the broader somatic symptom disorder category.', 4),
('f4000000-0000-0000-0000-000000000046', 'E', 'Normal variation in symptom reporting requiring no diagnosis', false, 'Ruled out because the persistence, distress, disproportionate health-related thoughts/behaviours, and significant functional impairment described exceed normal variation and represent a recognised clinical disorder.', 5),
('f4000000-0000-0000-0000-000000000047', 'A', 'Guillain-Barre syndrome', false, $x$Ruled out because GBS causes a genuine, progressive, symmetric weakness with reduced/absent reflexes on examination, not the inconsistent, incongruent examination findings (positive Hoover's sign) described here.$x$, 1),
('f4000000-0000-0000-0000-000000000047', 'B', 'Functional neurological symptom disorder (conversion disorder)', true, $x$Correct. Neurological symptoms (here, weakness) that are inconsistent with recognised neurological disease on examination (e.g. positive Hoover's sign, indicating involuntary hip extension strength during contralateral hip flexion despite reported weakness) and are not explained by another medical condition, causing significant distress or impairment, are characteristic of functional neurological symptom disorder.$x$, 2),
('f4000000-0000-0000-0000-000000000047', 'C', 'Multiple sclerosis', false, 'Ruled out because MS would typically show consistent neurological signs correlating with lesion location and, often, abnormalities on MRI, neither of which is present here.', 3),
('f4000000-0000-0000-0000-000000000047', 'D', 'Malingering', false, 'Ruled out because functional neurological symptom disorder involves genuine, unintentional symptom experience (the patient is not consciously fabricating symptoms), distinguishing it from malingering, which involves deliberate fabrication for external gain.', 4),
('f4000000-0000-0000-0000-000000000047', 'E', 'Simple deconditioning from inactivity', false, $x$Ruled out because the specific examination finding of a positive Hoover's sign (demonstrating incongruent, inconsistent motor findings) is a specific clinical sign supporting a functional neurological disorder, not simply generalised deconditioning.$x$, 5),
('f4000000-0000-0000-0000-000000000048', 'A', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves broad, pervasive worry across multiple life domains, not this specific, circumscribed fear focused on a single object (spiders).', 1),
('f4000000-0000-0000-0000-000000000048', 'B', 'Social anxiety disorder', false, 'Ruled out because social anxiety disorder involves fear of social or performance situations due to fear of judgement, not this fear of a specific non-social object.', 2),
('f4000000-0000-0000-0000-000000000048', 'C', 'Specific phobia', true, 'Correct. Marked, persistent, excessive fear of a specific object (here, spiders), with immediate anxiety response on exposure, avoidance behaviour, and recognition by the patient that the fear is excessive, is characteristic of a specific phobia.', 3),
('f4000000-0000-0000-0000-000000000048', 'D', 'Obsessive-compulsive disorder', false, 'Ruled out because OCD involves intrusive obsessions with associated compulsions performed to reduce anxiety, not simply a circumscribed fear response and avoidance of a specific object without described compulsive rituals.', 4),
('f4000000-0000-0000-0000-000000000048', 'E', 'Panic disorder', false, 'Ruled out because panic disorder involves recurrent, unexpected panic attacks not necessarily tied to a specific trigger, whereas this presentation describes anxiety specifically and consistently triggered by exposure to spiders.', 5),
('f4000000-0000-0000-0000-000000000049', 'A', 'SSRIs provide immediate relief of anxiety symptoms within hours of the first dose', false, 'Ruled out because SSRIs typically take several weeks to achieve their full therapeutic effect on anxiety symptoms, not hours; understanding this delayed onset is important for patient counselling and expectation-setting.', 1),
('f4000000-0000-0000-0000-000000000049', 'B', 'SSRIs have no effect on anxiety symptoms and are only used for depression', false, 'Ruled out because SSRIs are an established, effective first-line pharmacological treatment for several anxiety disorders, including panic disorder, not solely for depression.', 2),
('f4000000-0000-0000-0000-000000000049', 'C', 'SSRIs cause permanent worsening of anxiety symptoms that never improves', false, $x$Ruled out because although a temporary increase in anxiety can occur initially, this is expected to resolve as the medication's therapeutic benefit develops over subsequent weeks, not a permanent worsening.$x$, 3),
('f4000000-0000-0000-0000-000000000049', 'D', 'A temporary increase in anxiety symptoms can occur in the first 1-2 weeks of starting an SSRI, before the therapeutic benefit develops', true, $x$Correct. SSRIs can cause a temporary increase in anxiety symptoms (sometimes termed 'jitteriness' or activation) in the initial days to weeks of treatment, before the anticipated therapeutic anti-anxiety benefit develops over subsequent weeks; patients should be counselled about this and, where appropriate, a short-term benzodiazepine or low starting dose may be used to help manage this initial period.$x$, 4),
('f4000000-0000-0000-0000-000000000049', 'E', 'No specific counselling is needed regarding onset of effect or early symptom changes', false, 'Ruled out because appropriately counselling patients about the potential for early symptom exacerbation and the delayed onset of therapeutic benefit is important for treatment adherence and managing expectations.', 5),
('f4000000-0000-0000-0000-000000000050', 'A', 'Somatic symptom disorder', false, 'Ruled out because somatic symptom disorder is characterised primarily by the presence of significant, distressing physical symptoms with disproportionate associated thoughts/behaviours, whereas this patient has minimal or no actual physical symptoms; her preoccupation is specifically with the fear of illness itself, better characterised as illness anxiety disorder.', 1),
('f4000000-0000-0000-0000-000000000050', 'B', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves worry across multiple life domains, not this specific, focused preoccupation with having a serious illness.', 2),
('f4000000-0000-0000-0000-000000000050', 'C', 'Delusional disorder (somatic type)', false, $x$Ruled out because in illness anxiety disorder, the person's belief is anxious preoccupation rather than a fixed, unshakeable delusional conviction; some insight or ability to be reassured, even temporarily, typically persists, unlike a true delusion.$x$, 3),
('f4000000-0000-0000-0000-000000000050', 'D', 'Malingering', false, 'Ruled out because malingering involves conscious fabrication of symptoms for external gain, which differs fundamentally from the genuine, distressing anxiety about illness experienced in illness anxiety disorder.', 4),
('f4000000-0000-0000-0000-000000000050', 'E', 'Illness anxiety disorder', true, 'Correct. Persistent, high anxiety and preoccupation specifically about having or acquiring a serious illness, with minimal or no actual somatic symptoms, excessive health-related behaviours (checking, researching) or, alternatively, maladaptive avoidance, and persistence despite appropriate medical reassurance, is characteristic of illness anxiety disorder (previously termed hypochondriasis).', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f4000000-0000-0000-0000-000000000001', 'Core symptoms of depression (persistent low mood and/or anhedonia) present for most of the day, nearly every day, for at least two weeks are required for a diagnosis of a depressive episode.', 1),
('f4000000-0000-0000-0000-000000000001', 'Biological symptoms (sleep disturbance, appetite/weight change, psychomotor change) and cognitive symptoms (worthlessness, guilt, suicidal ideation) support the severity and diagnosis.', 2),
('f4000000-0000-0000-0000-000000000001', 'Absence of any prior manic/hypomanic history distinguishes unipolar major depressive disorder from bipolar disorder presenting with a depressive episode.', 3),
('f4000000-0000-0000-0000-000000000002', 'A distinct period of abnormally elevated, expansive or irritable mood, lasting at least a week (or requiring hospitalisation), with associated symptoms (grandiosity, reduced sleep need, pressured speech, risky behaviour) defines mania.', 1),
('f4000000-0000-0000-0000-000000000002', 'Significant functional impairment and impaired insight distinguish full mania from the milder, shorter hypomanic episode.', 2),
('f4000000-0000-0000-0000-000000000002', 'A manic episode, even in isolation, is sufficient to diagnose bipolar disorder, without necessarily requiring a prior depressive episode to have occurred first.', 3),
('f4000000-0000-0000-0000-000000000003', $x$Lithium impairs the kidney's ability to concentrate urine (nephrogenic diabetes insipidus) through effects on renal tubular cells, which can manifest as polyuria and polydipsia.$x$, 1),
('f4000000-0000-0000-0000-000000000003', 'Long-term lithium use carries a risk of progressive chronic kidney disease, making regular renal function monitoring an essential part of ongoing lithium therapy, alongside thyroid function and lithium level monitoring.', 2),
('f4000000-0000-0000-0000-000000000003', 'Lithium has a narrow therapeutic index, meaning both efficacy and toxicity are closely linked to plasma levels, reinforcing the importance of regular, proactive monitoring rather than reactive testing only when symptoms arise.', 3),
('f4000000-0000-0000-0000-000000000004', 'ACE inhibitors (and other drugs affecting renal sodium and water handling, such as thiazide diuretics and NSAIDs) are well-recognised to reduce lithium clearance, precipitating toxicity even without a change in the lithium dose itself.', 1),
('f4000000-0000-0000-0000-000000000004', 'Classic features of lithium toxicity include coarse tremor, ataxia, confusion, vomiting and, in severe cases, seizures and arrhythmias, reflecting its narrow therapeutic index.', 2),
('f4000000-0000-0000-0000-000000000004', 'Awareness of this interaction is important whenever prescribing new medications for patients on lithium, given the significant risk of precipitating toxicity through altered renal clearance.', 3),
('f4000000-0000-0000-0000-000000000005', 'ECT is specifically indicated for severe depression, particularly with high risk (significant suicidality, psychotic features, catatonia, or life-threatening physical decline such as refusal to eat/drink), where a rapid response is needed.', 1),
('f4000000-0000-0000-0000-000000000005', 'Treatment resistance (failure of multiple adequate medication trials) is a key indication supporting escalation to ECT when other options have been exhausted.', 2),
('f4000000-0000-0000-0000-000000000005', 'ECT often produces a more rapid antidepressant response than oral medication, which is particularly relevant in situations of acute, severe risk.', 3),
('f4000000-0000-0000-0000-000000000006', 'Hyperreflexia and clonus (rather than the hyporeflexia and rigidity of neuroleptic malignant syndrome) are key distinguishing features of serotonin syndrome.', 1),
('f4000000-0000-0000-0000-000000000006', 'Tramadol has additional serotonergic activity beyond its opioid effects, making its combination with an SSRI a recognised risk for precipitating serotonin syndrome.', 2),
('f4000000-0000-0000-0000-000000000006', 'Rapid onset (often within hours) after starting or increasing a serotonergic drug, or combining two serotonergic agents, is typical of serotonin syndrome, contrasting with the more gradual onset of NMS.', 3),
('f4000000-0000-0000-0000-000000000007', $x$Symptoms persisting or developing beyond the first two weeks postpartum, with functional impact, distinguish postnatal depression from the transient, milder 'baby blues.'$x$, 1),
('f4000000-0000-0000-0000-000000000007', 'Ego-dystonic intrusive thoughts (distressing, recognised as unwanted and not acted upon) are common in postnatal depression and anxiety and should be distinguished from the ego-syntonic, often command-type delusional beliefs seen in postpartum psychosis, which represents a psychiatric emergency.', 2),
('f4000000-0000-0000-0000-000000000007', 'Prompt recognition and treatment of postnatal depression is important given its impact on maternal wellbeing and the mother-infant relationship, alongside appropriate risk assessment regarding the intrusive thoughts described.', 3),
('f4000000-0000-0000-0000-000000000008', 'Chronicity (at least two years) with symptoms not severe enough to meet full major depressive episode criteria at most points is the defining feature of persistent depressive disorder.', 1),
('f4000000-0000-0000-0000-000000000008', $x$Patients with dysthymia can experience superimposed major depressive episodes on top of their chronic baseline symptoms, termed 'double depression,' which is important to recognise as it may require different or additional treatment.$x$, 2),
('f4000000-0000-0000-0000-000000000008', 'Distinguishing dysthymia from recurrent major depressive disorder (discrete episodes with periods of full recovery in between) is important for treatment planning and prognosis discussions.', 3),
('f4000000-0000-0000-0000-000000000009', $x$Sodium valproate's teratogenic risk (neural tube defects, neurodevelopmental disorders) is one of the most significant safety concerns among mood stabilisers, driving strict prescribing regulations.$x$, 1),
('f4000000-0000-0000-0000-000000000009', 'Regulatory guidance has extended precautionary advice to male patients regarding conception, reflecting a precautionary approach based on emerging evidence, alongside the long-established maternal risk.', 2),
('f4000000-0000-0000-0000-000000000009', 'Any medication changes in bipolar disorder around conception planning require careful specialist-led balancing of mood stability against reproductive safety considerations, rather than abrupt unilateral changes.', 3),
('f4000000-0000-0000-0000-000000000010', 'Depression with psychotic features (delusions, often mood-congruent themes such as guilt, nihilism, or poverty) is a distinct, more severe presentation requiring combination pharmacotherapy rather than antidepressant monotherapy.', 1),
('f4000000-0000-0000-0000-000000000010', $x$Nihilistic delusions (Cotard's syndrome-type beliefs, e.g. that one's organs are dead or rotting) are a classic mood-congruent psychotic feature seen in severe psychotic depression.$x$, 2),
('f4000000-0000-0000-0000-000000000010', 'ECT is a particularly effective treatment option for psychotic depression and may be considered especially where rapid response is needed or medication trials have been inadequate.', 3),
('f4000000-0000-0000-0000-000000000011', $x$Running commentary auditory hallucinations (voices discussing the patient's actions in the third person) are a classic 'first-rank' symptom historically associated with schizophrenia.$x$, 1),
('f4000000-0000-0000-0000-000000000011', 'A duration of symptoms exceeding 6 months, with significant functional decline, distinguishes schizophrenia from briefer psychotic presentations.', 2),
('f4000000-0000-0000-0000-000000000011', 'Excluding substance use and mood episodes as the cause is an essential step in diagnosing schizophrenia, as both can produce similar psychotic symptoms.', 3),
('f4000000-0000-0000-0000-000000000012', $x$Marked, generalised ('lead-pipe') muscle rigidity is a hallmark feature of NMS, distinguishing it from serotonin syndrome, which causes hyperreflexia and clonus instead.$x$, 1),
('f4000000-0000-0000-0000-000000000012', 'A markedly elevated creatine kinase reflects muscle breakdown from sustained rigidity, and helps confirm the diagnosis and monitor severity/complications such as acute kidney injury from rhabdomyolysis.', 2),
('f4000000-0000-0000-0000-000000000012', 'NMS typically develops over days (a slower onset than serotonin syndrome) after starting or increasing the dose of an antipsychotic, particularly high-potency first-generation agents like haloperidol.', 3),
('f4000000-0000-0000-0000-000000000013', 'Acute dystonic reactions typically occur within hours to a few days of starting or increasing the dose of an antipsychotic, particularly high-potency first-generation agents, reflecting acute dopamine blockade in the nigrostriatal pathway.', 1),
('f4000000-0000-0000-0000-000000000013', 'Anticholinergic medication (procyclidine, benztropine) provides rapid relief of acute dystonia by restoring the dopamine-acetylcholine balance in the basal ganglia.', 2),
('f4000000-0000-0000-0000-000000000013', 'Distinguishing acute dystonia from other extrapyramidal side effects (akathisia, parkinsonism, tardive dyskinesia) is important, as each has a different time course and specific management approach.', 3),
('f4000000-0000-0000-0000-000000000014', 'A delayed onset, typically after months to years of antipsychotic exposure, distinguishes tardive dyskinesia from the acute (dystonia) and subacute (parkinsonism, akathisia) extrapyramidal side effects.', 1),
('f4000000-0000-0000-0000-000000000014', 'Repetitive, involuntary orofacial and sometimes limb/truncal movements are the characteristic clinical pattern of tardive dyskinesia.', 2),
('f4000000-0000-0000-0000-000000000014', 'Unlike acute extrapyramidal effects, tardive dyskinesia can persist even after stopping the causative drug, making prevention through cautious, minimal-effective-dose prescribing particularly important.', 3),
('f4000000-0000-0000-0000-000000000015', $x$Clozapine's risk of agranulocytosis (severe neutropenia predisposing to life-threatening infection) is the defining safety concern requiring mandatory registration with a monitoring service and regular full blood counts.$x$, 1),
('f4000000-0000-0000-0000-000000000015', 'Monitoring frequency is highest early in treatment (weekly for the initial months) and can be reduced over time once stability is demonstrated, reflecting the pattern of when agranulocytosis risk is highest.', 2),
('f4000000-0000-0000-0000-000000000015', 'Clozapine is reserved for treatment-resistant schizophrenia (failure of at least two adequate antipsychotic trials) given this significant monitoring burden and side-effect profile, despite being highly effective in this population.', 3),
('f4000000-0000-0000-0000-000000000016', 'The core diagnostic principle for schizoaffective disorder is the presence of psychotic symptoms for a substantial period in the absence of a mood episode, alongside psychotic symptoms that also occur during mood episodes.', 1),
('f4000000-0000-0000-0000-000000000016', 'This distinguishes it from mood disorders with mood-congruent psychotic features, where psychosis occurs exclusively during mood episodes and resolves as the mood episode resolves.', 2),
('f4000000-0000-0000-0000-000000000016', 'Correctly distinguishing these diagnoses is clinically relevant, as it can influence treatment approach (relative emphasis on antipsychotic versus mood-stabilising/antidepressant treatment) and prognostic discussions.', 3),
('f4000000-0000-0000-0000-000000000017', 'Duration of symptoms is the key distinguishing feature among brief psychotic disorder (under one month), schizophreniform disorder (one to six months), and schizophrenia (over six months).', 1),
('f4000000-0000-0000-0000-000000000017', 'A clear precipitating stressor (such as sudden bereavement) is a recognised trigger for brief psychotic disorder, though this alone does not confirm the diagnosis without meeting the duration and recovery criteria.', 2),
('f4000000-0000-0000-0000-000000000017', 'Full return to premorbid functioning after resolution is a defining and reassuring feature of brief psychotic disorder, contrasting with the more variable, often incomplete recovery seen in schizophrenia.', 3),
('f4000000-0000-0000-0000-000000000018', 'A non-bizarre delusion (a belief that, while false, describes something that could theoretically occur, such as infidelity) is characteristic of delusional disorder, distinguishing it from the often bizarre delusions seen in schizophrenia.', 1),
('f4000000-0000-0000-0000-000000000018', 'Preserved functioning outside the specific delusional belief system, without other psychotic symptoms, is a key feature distinguishing delusional disorder from schizophrenia.', 2),
('f4000000-0000-0000-0000-000000000018', 'Morbid jealousy is a recognised subtype of delusional disorder and carries specific risk considerations, given the potential for the belief to drive controlling or even violent behaviour towards the (falsely) suspected partner.', 3),
('f4000000-0000-0000-0000-000000000019', 'Olanzapine and clozapine carry among the highest metabolic risk of the second-generation antipsychotics, including weight gain, dyslipidaemia and new-onset diabetes.', 1),
('f4000000-0000-0000-0000-000000000019', 'Regular metabolic monitoring (weight/BMI, blood glucose, lipid profile, blood pressure) is recommended at baseline and at regular intervals for patients on antipsychotic medication, particularly higher-risk agents like olanzapine.', 2),
('f4000000-0000-0000-0000-000000000019', 'Awareness of this risk profile can inform antipsychotic choice and the need for proactive lifestyle intervention and monitoring, balancing psychiatric efficacy against metabolic risk.', 3),
('f4000000-0000-0000-0000-000000000020', 'Negative symptoms reflect a loss or reduction of normal function (affect, speech, motivation, social engagement), in contrast to positive symptoms, which reflect an excess or distortion of normal function (hallucinations, delusions).', 1),
('f4000000-0000-0000-0000-000000000020', 'Negative symptoms are often more persistent and harder to treat pharmacologically than positive symptoms, contributing significantly to long-term functional impairment in schizophrenia.', 2),
('f4000000-0000-0000-0000-000000000020', 'Distinguishing negative symptoms from depression (which can present similarly with reduced motivation and social withdrawal) is clinically important, as it affects treatment approach.', 3),
('f4000000-0000-0000-0000-000000000021', 'Delirium tremens classically develops 48-96 hours after the last drink, distinguishing it temporally from earlier, milder withdrawal symptoms and from acute intoxication.', 1),
('f4000000-0000-0000-0000-000000000021', 'Marked autonomic hyperactivity (tachycardia, hypertension, hyperthermia) alongside confusion and hallucinations reflects the severity of this withdrawal state and its potential to be life-threatening if untreated.', 2),
('f4000000-0000-0000-0000-000000000021', 'Benzodiazepines are the mainstay of treatment for alcohol withdrawal and delirium tremens, both treating symptoms and preventing progression to withdrawal seizures.', 3),
('f4000000-0000-0000-0000-000000000022', $x$Chronic alcohol misuse impairs thiamine absorption, storage and utilisation, making affected patients particularly vulnerable to precipitating Wernicke's encephalopathy when glucose is administered.$x$, 1),
('f4000000-0000-0000-0000-000000000022', $x$The principle of 'thiamine before glucose' in at-risk patients is a well-established, important patient safety point in managing patients with chronic alcohol misuse.$x$, 2),
('f4000000-0000-0000-0000-000000000022', $x$Prophylactic (rather than purely reactive) thiamine administration reflects the preventable nature of Wernicke's encephalopathy and the severe, potentially irreversible consequences (Korsakoff syndrome) if it develops untreated.$x$, 3),
('f4000000-0000-0000-0000-000000000023', $x$Korsakoff syndrome represents the chronic, often irreversible sequela of Wernicke's encephalopathy when thiamine deficiency is not treated promptly or adequately, reflecting damage to structures including the mammillary bodies and thalamus.$x$, 1),
('f4000000-0000-0000-0000-000000000023', 'Confabulation (unconsciously fabricating information to fill memory gaps, without intent to deceive) alongside severe anterograde amnesia, with relative preservation of other cognitive functions, is the classic pattern of Korsakoff syndrome.', 2),
('f4000000-0000-0000-0000-000000000023', $x$Prompt, adequate thiamine treatment during the acute Wernicke's phase is important specifically to try to prevent progression to this often permanent memory disorder.$x$, 3),
('f4000000-0000-0000-0000-000000000024', 'The triad of pinpoint pupils, respiratory depression and reduced consciousness is classic for opioid toxicity/overdose.', 1),
('f4000000-0000-0000-0000-000000000024', $x$Naloxone acts as a competitive opioid receptor antagonist, rapidly reversing respiratory depression, though repeated doses or an infusion may be needed given naloxone's shorter half-life compared with many opioids (risk of re-sedation).$x$, 2),
('f4000000-0000-0000-0000-000000000024', 'Patients should be monitored after naloxone reversal, given the risk of recurrent respiratory depression as the naloxone effect wears off before the opioid has been fully cleared.', 3),
('f4000000-0000-0000-0000-000000000025', 'Methadone (full agonist, longer-acting) and buprenorphine (partial agonist, with a ceiling effect reducing overdose risk) are the two main evidence-based options for opioid substitution therapy.', 1),
('f4000000-0000-0000-0000-000000000025', 'Substitution therapy aims to stabilise the patient on a controlled, prescribed opioid, reducing the harms associated with illicit opioid use, rather than necessarily achieving immediate abstinence.', 2),
('f4000000-0000-0000-0000-000000000025', 'Choice between methadone and buprenorphine depends on individual patient factors, including risk profile, other substance use, and personal preference, alongside appropriate psychosocial support.', 3),
('f4000000-0000-0000-0000-000000000026', $x$Methadone's QT-prolonging effect is dose-dependent and represents a well-established, clinically important safety consideration in patients on opioid substitution therapy.$x$, 1),
('f4000000-0000-0000-0000-000000000026', 'Certain antibiotics (e.g. some macrolides, fluoroquinolones) and other drugs can either independently prolong the QT interval or inhibit methadone metabolism (raising methadone levels), compounding torsades de pointes risk.', 2),
('f4000000-0000-0000-0000-000000000026', 'Baseline and periodic ECG monitoring, along with careful review of new medications for QT-prolonging or interacting potential, is recommended for patients on methadone maintenance therapy.', 3),
('f4000000-0000-0000-0000-000000000027', 'An AST:ALT ratio greater than 2:1 is a relatively specific (though not universally sensitive) pattern suggesting alcohol-related liver disease, contrasting with the ALT-predominant pattern typical of most other liver diseases.', 1),
('f4000000-0000-0000-0000-000000000027', 'A markedly raised gamma-GT, particularly when disproportionate to other liver enzymes, is a sensitive marker of alcohol consumption, though it can also be elevated by other causes (e.g. certain medications, biliary disease).', 2),
('f4000000-0000-0000-0000-000000000027', 'Recognising this biochemical pattern supports appropriate counselling regarding alcohol reduction/cessation as part of managing the underlying liver disease.', 3),
('f4000000-0000-0000-0000-000000000028', $x$Cocaine's mechanism of blocking catecholamine reuptake produces a classic sympathomimetic toxidrome: agitation, mydriasis, tachycardia, hypertension and hyperthermia.$x$, 1),
('f4000000-0000-0000-0000-000000000028', 'Cocaine-associated chest pain reflects coronary vasospasm and increased myocardial oxygen demand, carrying a genuine risk of myocardial infarction even in young patients without underlying coronary disease.', 2),
('f4000000-0000-0000-0000-000000000028', 'Beta-blockers are generally avoided in cocaine-associated chest pain/hypertension due to the risk of unopposed alpha-adrenergic vasoconstriction worsening coronary vasospasm; benzodiazepines are typically used first-line instead.', 3),
('f4000000-0000-0000-0000-000000000029', 'Abrupt benzodiazepine withdrawal after prolonged, high-dose use carries a significant risk of severe complications, including withdrawal seizures, distinguishing it from milder, shorter-term use.', 1),
('f4000000-0000-0000-0000-000000000029', 'Gradual dose tapering, sometimes via conversion to a longer-acting benzodiazepine (e.g. diazepam) to allow smoother reduction, is the standard, safer approach to discontinuation.', 2),
('f4000000-0000-0000-0000-000000000029', 'The rate of tapering is individualised based on the dose, duration of use, and patient-specific factors, reflecting a structured, supervised approach rather than a fixed, rapid schedule.', 3),
('f4000000-0000-0000-0000-000000000030', 'Validated screening tools like AUDIT provide a structured, evidence-based way to quantify alcohol-related risk, distinguishing low-risk, hazardous, harmful and likely dependent drinking patterns.', 1),
('f4000000-0000-0000-0000-000000000030', 'Brief intervention (structured advice and discussion) following a positive screen is an effective, evidence-based approach for many patients with hazardous or harmful (non-dependent) drinking, without necessarily requiring specialist referral.', 2),
('f4000000-0000-0000-0000-000000000030', 'Screening and early intervention aim to identify and address risky drinking patterns before they progress to more severe alcohol-related harm or dependence.', 3),
('f4000000-0000-0000-0000-000000000031', 'Capacity is decision-specific and time-specific: a person may lack capacity for one decision (e.g. complex surgery) while retaining it for simpler decisions, and capacity can fluctuate over time.', 1),
('f4000000-0000-0000-0000-000000000031', 'The standard capacity test requires the person to understand, retain, weigh/use the relevant information, and communicate their decision; failure in any of these elements can indicate a lack of capacity for that decision.', 2),
('f4000000-0000-0000-0000-000000000031', 'A diagnosis (such as dementia) alone does not equate to lack of capacity; a specific, structured assessment of the particular decision is always required.', 3),
('f4000000-0000-0000-0000-000000000032', $x$The Mental Health Act specifically addresses situations where a person's mental disorder itself is driving risk and refusal of necessary treatment for that disorder, distinguishing it from the Mental Capacity Act, which addresses decision-making capacity more broadly across various types of decisions.$x$, 1),
('f4000000-0000-0000-0000-000000000032', 'Formal assessment by appropriately qualified professionals (as specified in Mental Health Act processes) is required before detention, ensuring proper legal safeguards are followed even in urgent situations.', 2),
('f4000000-0000-0000-0000-000000000032', 'The presence of significant risk (to self or others) arising from the mental disorder, combined with refusal of voluntary treatment, is central to the threshold for considering Mental Health Act assessment.', 3),
('f4000000-0000-0000-0000-000000000033', $x$The Mental Health Act's applicability does not depend on the patient lacking capacity; it can be used even in a capacitous patient refusing treatment for their mental disorder, provided legal criteria relating to risk and diagnosis are met.$x$, 1),
('f4000000-0000-0000-0000-000000000033', 'The Mental Capacity Act applies broadly to any decision (physical or mental health, financial, welfare) where a person lacks the capacity to make that specific decision, requiring a best interests approach.', 2),
('f4000000-0000-0000-0000-000000000033', 'Correctly identifying which legal framework applies in a given clinical scenario is essential for ensuring both appropriate patient care and legal compliance, as the criteria, safeguards and processes differ between the two Acts.', 3),
('f4000000-0000-0000-0000-000000000034', 'Detention under the Mental Health Act comes with specific, legally mandated safeguards, including the right to appeal, access to independent advocacy, and regular review, balancing necessary treatment against protection of patient rights.', 1),
('f4000000-0000-0000-0000-000000000034', 'Understanding these retained rights is important both for patient care and for ensuring legal compliance by treating teams.', 2),
('f4000000-0000-0000-0000-000000000034', 'The existence of a formal appeal process (Mental Health Tribunal) reflects the legal principle that detention, while permitted under specific criteria, must remain subject to independent scrutiny and challenge.', 3),
('f4000000-0000-0000-0000-000000000035', $x$Severe eating disorders can specifically and significantly impair the 'weighing' element of capacity (using information to arrive at a decision) even when a person appears otherwise cognitively intact and can articulate their views clearly.$x$, 1),
('f4000000-0000-0000-0000-000000000035', 'A structured, formal capacity assessment specific to the decision at hand (accepting nutritional treatment) is essential before concluding that a refusal should be respected or overridden.', 2),
('f4000000-0000-0000-0000-000000000035', 'Where capacity is found to be lacking and significant risk exists, the Mental Health Act may be the appropriate framework, given that the impairment relates directly to a mental disorder (anorexia nervosa) and its effect on the ability to make treatment decisions.', 3),
('f4000000-0000-0000-0000-000000000036', 'The four-part capacity test (understand, retain, use/weigh, communicate) allows precise identification of which specific element is impaired, which can vary between patients and conditions.', 1),
('f4000000-0000-0000-0000-000000000036', $x$Simply repeating information back demonstrates retention, not necessarily the higher-order ability to apply that information meaningfully to one's own situation (the 'use or weigh' element).$x$, 2),
('f4000000-0000-0000-0000-000000000036', $x$Identifying the specific impaired element can sometimes guide supportive measures (e.g. additional explanation, involving family, using different communication approaches) to try to maximise the person's capacity for the decision, as required before concluding they lack capacity.$x$, 3),
('f4000000-0000-0000-0000-000000000037', 'The presumption of capacity is a foundational legal and ethical principle, protecting patient autonomy and preventing capacity from being wrongly assumed to be absent without proper justification.', 1),
('f4000000-0000-0000-0000-000000000037', 'This presumption applies regardless of the nature of the decision or whether it appears unwise to others, reinforcing that capacity assessment focuses on the decision-making process, not the outcome of the decision itself.', 2),
('f4000000-0000-0000-0000-000000000037', $x$Only when there is a genuine question about a person's ability to understand, retain, use/weigh, or communicate a decision should a formal capacity assessment be undertaken, starting from this presumption.$x$, 3),
('f4000000-0000-0000-0000-000000000038', 'IMCAs are specifically provided for people who lack capacity for significant decisions and have no other appropriate person (family or friends) to consult, ensuring their voice is still represented in the decision-making process.', 1),
('f4000000-0000-0000-0000-000000000038', $x$The IMCA role is distinct from and independent of the treating clinical team, providing a genuinely separate perspective focused on the person's best interests.$x$, 2),
('f4000000-0000-0000-0000-000000000038', 'Involving an IMCA is a legal requirement (not simply good practice) in specific circumstances (e.g. serious medical treatment decisions for unbefriended patients lacking capacity), reflecting the importance of this safeguard.', 3),
('f4000000-0000-0000-0000-000000000039', 'An advance decision to refuse treatment, made validly by a person with capacity, remains legally binding even after they lose capacity, provided it is both valid (properly made and not withdrawn) and applicable to the specific situation that has arisen.', 1),
('f4000000-0000-0000-0000-000000000039', $x$This principle upholds patient autonomy, allowing a person's clearly expressed wishes about future treatment to be respected even when they can no longer communicate them directly.$x$, 2),
('f4000000-0000-0000-0000-000000000039', 'Careful verification that the advance decision is genuinely valid and specifically applicable to the current clinical situation (e.g. specifying refusal of blood products in this type of circumstance) is an important part of appropriately acting on it.', 3),
('f4000000-0000-0000-0000-000000000040', 'Informal admission means the patient has not been detained under the Mental Health Act and retains the right to leave at any time, a fundamental distinction from detained status.', 1),
('f4000000-0000-0000-0000-000000000040', 'Specific short-term holding powers exist to allow assessment to take place when a patient wishes to leave but there is a genuine concern about risk, bridging the gap until a full Mental Health Act assessment can be completed.', 2),
('f4000000-0000-0000-0000-000000000040', $x$Any restriction on an informal patient's freedom to leave must follow the proper legal process; acting outside this framework, even with good clinical intentions, would be unlawful.$x$, 3),
('f4000000-0000-0000-0000-000000000041', 'Worry that is excessive, difficult to control, and spans multiple domains of life (rather than being focused on a single specific fear or discrete attacks) is characteristic of generalised anxiety disorder.', 1),
('f4000000-0000-0000-0000-000000000041', 'A duration of at least six months, with associated physical symptoms (muscle tension, restlessness) and cognitive symptoms (poor concentration), supports the diagnosis.', 2),
('f4000000-0000-0000-0000-000000000041', 'Distinguishing GAD from panic disorder (episodic, acute attacks) and specific phobia (circumscribed trigger) is based on the pattern, breadth and persistence of the anxiety symptoms.', 3),
('f4000000-0000-0000-0000-000000000042', 'Discrete panic attacks, peaking within minutes with characteristic physical and cognitive symptoms (palpitations, fear of dying), distinguish panic disorder from the more persistent, lower-grade symptoms of GAD.', 1),
('f4000000-0000-0000-0000-000000000042', 'Anticipatory anxiety about having further attacks, and associated avoidance behaviour (e.g. of public places, sometimes progressing to agoraphobia), is a common feature of established panic disorder.', 2),
('f4000000-0000-0000-0000-000000000042', 'Organic causes (cardiac, thyroid, substance-related) should be appropriately considered and excluded, particularly on first presentation, before confirming a primary panic disorder diagnosis.', 3),
('f4000000-0000-0000-0000-000000000043', 'The core fear in social anxiety disorder is specifically of negative evaluation, judgement or embarrassment by others in social or performance situations, distinguishing it from the broader worry of GAD or the escape-related fear of agoraphobia.', 1),
('f4000000-0000-0000-0000-000000000043', 'Avoidance of a range of social and performance situations, with significant functional impact (here, career progression), supports the diagnosis and reflects its severity.', 2),
('f4000000-0000-0000-0000-000000000043', 'Physical symptoms (blushing, trembling, nausea) occurring specifically in social/performance contexts reinforce the situational specificity characteristic of this disorder.', 3),
('f4000000-0000-0000-0000-000000000044', 'Ego-dystonic obsessions (recognised by the patient as excessive, irrational, and unwanted, causing them distress) distinguish OCD from delusional beliefs, which are held with fixed conviction.', 1),
('f4000000-0000-0000-0000-000000000044', 'Compulsions are repetitive behaviours or mental acts performed specifically to reduce the anxiety or distress generated by the obsessions, forming the characteristic obsession-compulsion cycle of OCD.', 2),
('f4000000-0000-0000-0000-000000000044', 'Significant functional impairment (time consumed by rituals, interference with daily life) is required to distinguish clinical OCD from milder, non-pathological checking or cleanliness preferences.', 3),
('f4000000-0000-0000-0000-000000000045', 'PTSD requires exposure to a traumatic event followed by a specific symptom cluster: re-experiencing (flashbacks, nightmares), avoidance, negative alterations in mood/cognition, and hyperarousal, persisting beyond one month.', 1),
('f4000000-0000-0000-0000-000000000045', 'Acute stress reaction/disorder describes a similar but more transient presentation occurring within the first month, distinguishing it from the more persistent PTSD.', 2),
('f4000000-0000-0000-0000-000000000045', 'The combination of intrusive re-experiencing symptoms with both avoidance and hyperarousal (rather than any single symptom domain alone) is required for the full PTSD diagnosis.', 3),
('f4000000-0000-0000-0000-000000000046', 'Somatic symptom disorder is characterised not just by the presence of physical symptoms, but by disproportionate, excessive thoughts, feelings, or behaviours related to those symptoms, regardless of whether an organic cause is found.', 1),
('f4000000-0000-0000-0000-000000000046', 'This distinguishes it from malingering and factitious disorder, both of which involve conscious symptom fabrication for external or internal gain respectively, unlike the genuine, unintentional distress in somatic symptom disorder.', 2),
('f4000000-0000-0000-0000-000000000046', $x$Management typically involves a collaborative approach combining medical reassurance with psychological therapy, avoiding both dismissal of the patient's distress and excessive further unnecessary investigation.$x$, 3),
('f4000000-0000-0000-0000-000000000047', $x$Positive Hoover's sign (weakness on direct hip extension testing that resolves during contralateral hip flexion, demonstrating involuntary normal strength) is a specific, clinically useful sign supporting a functional (rather than organic) cause of leg weakness.$x$, 1),
('f4000000-0000-0000-0000-000000000047', 'Inconsistency of findings on examination (e.g. variable effort, non-anatomical patterns) helps distinguish functional neurological symptom disorder from a genuine structural or demyelinating neurological process.', 2),
('f4000000-0000-0000-0000-000000000047', 'This diagnosis reflects genuine, unintentional symptoms (unlike malingering) arising through a recognised, though incompletely understood, psychological-neurological mechanism, and management involves specific functional neurological rehabilitation approaches rather than simply reassurance alone.', 3),
('f4000000-0000-0000-0000-000000000048', 'A specific, circumscribed trigger (a particular object, animal or situation) provoking a consistent, immediate fear response distinguishes specific phobia from the broader, more pervasive anxiety disorders.', 1),
('f4000000-0000-0000-0000-000000000048', 'Insight that the fear is excessive or unreasonable, combined with the anxiety response and avoidance behaviour, supports the diagnosis of a phobic disorder.', 2),
('f4000000-0000-0000-0000-000000000048', 'Significant functional impact (here, avoidance of parks and gardens) helps distinguish a clinically significant phobia from a common, milder fear that does not warrant a formal diagnosis.', 3),
('f4000000-0000-0000-0000-000000000049', 'The delayed onset of SSRI therapeutic benefit (typically several weeks) is an important counselling point, distinguishing it from the rapid onset of benzodiazepines (though these carry dependence risk with longer-term use).', 1),
('f4000000-0000-0000-0000-000000000049', 'Early activation/increased anxiety in the first 1-2 weeks of SSRI treatment is a recognised phenomenon that can affect adherence if patients are not properly counselled about it in advance.', 2),
('f4000000-0000-0000-0000-000000000049', 'Starting at a lower dose and/or brief concurrent benzodiazepine use are strategies sometimes used to help manage this initial period in anxiety disorders, though this requires careful individual risk-benefit consideration.', 3),
('f4000000-0000-0000-0000-000000000050', 'Illness anxiety disorder is distinguished from somatic symptom disorder by the relative absence of significant physical symptoms; the focus is specifically on fear and preoccupation about illness itself.', 1),
('f4000000-0000-0000-0000-000000000050', 'Excessive health-related behaviours (repeated checking, reassurance-seeking, extensive research) or, in some patients, maladaptive avoidance of medical care, are characteristic behavioural features.', 2),
('f4000000-0000-0000-0000-000000000050', 'Persistence of the preoccupation despite appropriate medical evaluation and reassurance is a key diagnostic feature, distinguishing this from normal, transient health concerns.', 3);
